// Helper: Ambil PIN Guru Resmi (Multi-Lapisan: localStorage, Cookie, sessionStorage)
function getTeacherPin() {
  try {
    const ls = localStorage.getItem(GURU_PIN_KEY);
    if (ls && ls.trim()) {
      const trimmed = ls.trim();
      if (trimmed === '1234') return DEFAULT_GURU_PIN; // Migrasikan PIN lama 1234 ke default baru 003734
      return trimmed;
    }
  } catch (e) {}
  try {
    const m = document.cookie.match(new RegExp('(?:^|;\\s*)' + GURU_PIN_KEY + '=([^;]+)'));
    if (m && m[1]) {
      const decoded = decodeURIComponent(m[1]).trim();
      if (decoded) {
        if (decoded === '1234') return DEFAULT_GURU_PIN;
        return decoded;
      }
    }
  } catch (e) {}
  try {
    const ss = sessionStorage.getItem(GURU_PIN_KEY);
    if (ss && ss.trim()) {
      const trimmedSs = ss.trim();
      if (trimmedSs === '1234') return DEFAULT_GURU_PIN;
      return trimmedSs;
    }
  } catch (e) {}
  return DEFAULT_GURU_PIN;
}
window.getTeacherPin = getTeacherPin;

// Helper: Simpan PIN Guru Baru (Multi-Lapisan: localStorage, Cookie 365 hari, sessionStorage)
function saveTeacherPin(pin) {
  const cleanPin = (pin || '').toString().trim();
  if (!cleanPin) return;
  try { localStorage.setItem(GURU_PIN_KEY, cleanPin); } catch (e) {}
  try { sessionStorage.setItem(GURU_PIN_KEY, cleanPin); } catch (e) {}
  try {
    const d = new Date();
    d.setTime(d.getTime() + (365 * 24 * 60 * 60 * 1000)); // 1 tahun
    document.cookie = `${GURU_PIN_KEY}=${encodeURIComponent(cleanPin)};expires=${d.toUTCString()};path=/;SameSite=Lax`;
  } catch (e) {}
}
window.saveTeacherPin = saveTeacherPin;

// Helper: Reset PIN Guru ke Default 1234
function clearTeacherPin() {
  try { localStorage.removeItem(GURU_PIN_KEY); } catch (e) {}
  try { sessionStorage.removeItem(GURU_PIN_KEY); } catch (e) {}
  try {
    document.cookie = `${GURU_PIN_KEY}=;expires=Thu, 01 Jan 1970 00:00:00 UTC;path=/;SameSite=Lax`;
  } catch (e) {}
}
window.clearTeacherPin = clearTeacherPin;

// Helper: Ambil URL Webhook Google Apps Script (Multi-Lapisan: localStorage, Cookie, sessionStorage)
function getPersistentWebhookUrl() {
  try {
    const ls = localStorage.getItem(WEBHOOK_KEY);
    if (ls && ls.trim()) return ls.trim();
  } catch (e) {}
  try {
    const m = document.cookie.match(new RegExp('(?:^|;\\s*)' + WEBHOOK_KEY + '=([^;]+)'));
    if (m && m[1]) {
      const decoded = decodeURIComponent(m[1]).trim();
      if (decoded) return decoded;
    }
  } catch (e) {}
  try {
    const ss = sessionStorage.getItem(WEBHOOK_KEY);
    if (ss && ss.trim()) return ss.trim();
  } catch (e) {}
  return '';
}
window.getPersistentWebhookUrl = getPersistentWebhookUrl;

// Helper: Simpan URL Webhook Google Apps Script (Multi-Lapisan: localStorage, Cookie 365 hari, sessionStorage)
function savePersistentWebhookUrl(url) {
  const cleanUrl = (url || '').toString().trim();
  if (cleanUrl) {
    try { localStorage.setItem(WEBHOOK_KEY, cleanUrl); } catch (e) {}
    try { sessionStorage.setItem(WEBHOOK_KEY, cleanUrl); } catch (e) {}
    try {
      const d = new Date();
      d.setTime(d.getTime() + (365 * 24 * 60 * 60 * 1000)); // 1 tahun
      document.cookie = `${WEBHOOK_KEY}=${encodeURIComponent(cleanUrl)};expires=${d.toUTCString()};path=/;SameSite=Lax`;
    } catch (e) {}
  } else {
    try { localStorage.removeItem(WEBHOOK_KEY); } catch (e) {}
    try { sessionStorage.removeItem(WEBHOOK_KEY); } catch (e) {}
    try {
      document.cookie = `${WEBHOOK_KEY}=;expires=Thu, 01 Jan 1970 00:00:00 UTC;path=/;SameSite=Lax`;
    } catch (e) {}
  }
}
window.savePersistentWebhookUrl = savePersistentWebhookUrl;

// Helper: Cek Status Sesi Guru Aktif (Multi-Lapisan: window, localStorage, sessionStorage, Cookie)
function isTeacherSessionActive() {
  if (window.__TEACHER_SESSION_ACTIVE__ === true) return true;
  try {
    const ls = localStorage.getItem(TEACHER_SESSION_KEY);
    if (ls === 'ACTIVE') return true;
  } catch (e) {}
  try {
    const ss = sessionStorage.getItem(TEACHER_SESSION_KEY);
    if (ss === 'ACTIVE') return true;
  } catch (e) {}
  try {
    const m = document.cookie.match(new RegExp('(?:^|;\\s*)' + TEACHER_SESSION_KEY + '=([^;]+)'));
    if (m && m[1] === 'ACTIVE') return true;
  } catch (e) {}
  return false;
}
window.isTeacherSessionActive = isTeacherSessionActive;

// Helper: Simpan atau Hapus Sesi Guru (Multi-Lapisan)
function setTeacherSessionActive(isActive) {
  window.__TEACHER_SESSION_ACTIVE__ = !!isActive;
  if (typeof state !== 'undefined') {
    state.isGuruLoggedIn = !!isActive;
  }
  if (isActive) {
    try { localStorage.setItem(TEACHER_SESSION_KEY, 'ACTIVE'); } catch (e) {}
    try { sessionStorage.setItem(TEACHER_SESSION_KEY, 'ACTIVE'); } catch (e) {}
    try {
      const d = new Date();
      d.setTime(d.getTime() + (30 * 24 * 60 * 60 * 1000)); // 30 hari
      document.cookie = `${TEACHER_SESSION_KEY}=ACTIVE;expires=${d.toUTCString()};path=/;SameSite=Lax`;
    } catch (e) {}
  } else {
    try { localStorage.removeItem(TEACHER_SESSION_KEY); } catch (e) {}
    try { sessionStorage.removeItem(TEACHER_SESSION_KEY); } catch (e) {}
    try {
      document.cookie = `${TEACHER_SESSION_KEY}=LOGGED_OUT;expires=Thu, 01 Jan 1970 00:00:00 UTC;path=/;SameSite=Lax`;
    } catch (e) {}
    const earlyGuruStyle = document.getElementById('style-early-teacher-session');
    if (earlyGuruStyle) {
      earlyGuruStyle.remove();
    }
  }
}
window.setTeacherSessionActive = setTeacherSessionActive;

// Helper: Ambil Profil Siswa Aktif (Dukungan Multi-Lapisan: window, localStorage, sessionStorage, Cookie)
function getActiveStudentProfile() {
  try {
    // 1. Cek cache memori window
    if (window.__ACTIVE_STUDENT_PROFILE__ && (window.__ACTIVE_STUDENT_PROFILE__.nama || window.__ACTIVE_STUDENT_PROFILE__.nis || window.__ACTIVE_STUDENT_PROFILE__.id)) {
      return window.__ACTIVE_STUDENT_PROFILE__;
    }

    let raw = null;

    // 2. Cek localStorage secara terisolasi (Abaikan jika nilai penanda keluar LOGGED_OUT)
    try {
      const ls = localStorage.getItem(ACTIVE_STUDENT_KEY);
      if (ls && ls !== 'LOGGED_OUT' && ls !== 'null' && ls !== 'undefined' && ls.indexOf('{') !== -1) {
        raw = ls;
      }
    } catch (eLs) {}

    // 3. Cek sessionStorage jika belum dapat dari localStorage
    if (!raw) {
      try {
        const ss = sessionStorage.getItem(ACTIVE_STUDENT_KEY);
        if (ss && ss !== 'LOGGED_OUT' && ss !== 'null' && ss !== 'undefined' && ss.indexOf('{') !== -1) {
          raw = ss;
        }
      } catch (eSs) {}
    }

    // 4. Cek document.cookie sebagai pengaman cadangan peramban
    if (!raw) {
      try {
        const m = document.cookie.match(new RegExp('(?:^|;\\s*)' + ACTIVE_STUDENT_KEY + '=([^;]+)'));
        if (m && m[1]) {
          const ck = decodeURIComponent(m[1]);
          if (ck && ck !== 'LOGGED_OUT' && ck !== 'null' && ck !== 'undefined' && ck.indexOf('{') !== -1) {
            raw = ck;
          }
        }
      } catch (eCk) {}
    }

    if (!raw) {
      return null;
    }

    const parsed = JSON.parse(raw);
    if (parsed && (parsed.nama || parsed.nis || parsed.id)) {
      window.__ACTIVE_STUDENT_PROFILE__ = parsed;
      window.__ACTIVE_STUDENT_RESTORED__ = parsed;
      // Sinkronkan ke seluruh penyimpanan agar selalu persisten di reload (F5)
      try { localStorage.setItem(ACTIVE_STUDENT_KEY, raw); } catch (e) {}
      try { sessionStorage.setItem(ACTIVE_STUDENT_KEY, raw); } catch (e) {}
      try { document.cookie = ACTIVE_STUDENT_KEY + '=' + encodeURIComponent(raw) + '; path=/; max-age=31536000'; } catch (e) {}
      return parsed;
    }
    return null;
  } catch (e) {
    return null;
  }
}
window.getActiveStudentProfile = getActiveStudentProfile;

