// Helper: Simpan Sesi Siswa Aktif ke Seluruh Lapisan Penyimpanan
function saveActiveStudentSession(profile, targetTab = null) {
  if (!profile) return;
  window.__ACTIVE_STUDENT_PROFILE__ = profile;
  window.__ACTIVE_STUDENT_RESTORED__ = profile;

  // PENTING: Untuk cookie browser, buang gambar base64 besar (driveData) agar tidak melampaui batas 4KB cookie
  const cookieProfile = { ...profile };
  delete cookieProfile.driveData;
  const rawCookie = JSON.stringify(cookieProfile);
  const raw = JSON.stringify(profile);

  try { localStorage.setItem(ACTIVE_STUDENT_KEY, raw); } catch (e) {}
  try { sessionStorage.setItem(ACTIVE_STUDENT_KEY, raw); } catch (e) {}
  try { document.cookie = ACTIVE_STUDENT_KEY + '=' + encodeURIComponent(rawCookie) + '; path=/; max-age=31536000'; } catch (e) {}

  if (targetTab) {
    try { localStorage.setItem(ACTIVE_TAB_KEY, targetTab); } catch (e) {}
    try { sessionStorage.setItem(ACTIVE_TAB_KEY, targetTab); } catch (e) {}
  }
  try { localStorage.setItem(ACTIVE_SEM_KEY, String((typeof state !== 'undefined' && state.currentSemester) ? state.currentSemester : 1)); } catch (e) {}
  try { sessionStorage.setItem(ACTIVE_SEM_KEY, String((typeof state !== 'undefined' && state.currentSemester) ? state.currentSemester : 1)); } catch (e) {}

  // Injeksi style CSS agar instan sembunyikan login dan tampilkan logout seketika tanpa perlu refresh (F5)
  try { injectOrUpdateStudentStyle(profile); } catch (eStyle) {}

  // Sinkronkan tampilan bar profil siswa seketika ke DOM
  try {
    if (typeof muatProfilSiswa === 'function') {
      muatProfilSiswa();
    }
  } catch (eMuat) {}
}
window.saveActiveStudentSession = saveActiveStudentSession;

// Helper: Bersihkan Sesi Siswa Aktif (HANYA Saat Siswa Sengaja Mengklik Tombol Keluar)
function clearActiveStudentSession() {
  window.__ACTIVE_STUDENT_PROFILE__ = null;
  window.__ACTIVE_STUDENT_RESTORED__ = null;
  try { localStorage.removeItem(ACTIVE_STUDENT_KEY); } catch (e) {}
  try { sessionStorage.removeItem(ACTIVE_STUDENT_KEY); } catch (e) {}
  try { localStorage.setItem(ACTIVE_STUDENT_KEY, 'LOGGED_OUT'); } catch (e) {}
  try { sessionStorage.setItem(ACTIVE_STUDENT_KEY, 'LOGGED_OUT'); } catch (e) {}
  try { document.cookie = ACTIVE_STUDENT_KEY + '=LOGGED_OUT; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;'; } catch (e) {}
  try { document.cookie = ACTIVE_STUDENT_KEY + '=LOGGED_OUT; path=/; max-age=0;'; } catch (e) {}
  try { document.cookie = ACTIVE_STUDENT_KEY + '=; expires=Thu, 01 Jan 1970 00:00:00 UTC; path=/;'; } catch (e) {}
  try { localStorage.removeItem(ACTIVE_TAB_KEY); } catch (e) {}
  try { sessionStorage.removeItem(ACTIVE_TAB_KEY); } catch (e) {}
  try { localStorage.removeItem(ACTIVE_SEM_KEY); } catch (e) {}
  try { sessionStorage.removeItem(ACTIVE_SEM_KEY); } catch (e) {}

  const earlyStyle = document.getElementById('style-early-student-session');
  if (earlyStyle) earlyStyle.remove();
  const cardsSiswa = document.getElementById('beranda-fitur-cards-siswa');
  if (cardsSiswa) cardsSiswa.classList.add('hidden');
}
window.clearActiveStudentSession = clearActiveStudentSession;

// Helper: Dapatkan kunci penyimpanan terisolasi per akun siswa (berdasarkan NIS unik / ID siswa)
function getActiveStudentStorageKey(prefix = 'kreator_cilik_word_posters') {
  const profile = (typeof getActiveStudentProfile === 'function') ? getActiveStudentProfile() : null;
  if (profile && (profile.nis || profile.id || profile.nama)) {
    const rawId = profile.nis || profile.id || `${profile.kelas || '4'}_${profile.nama}`;
    const cleanId = String(rawId).replace(/[^a-zA-Z0-9_-]/g, '_');
    return `${prefix}_${cleanId}`;
  }
  return `${prefix}_guest`;
}
window.getActiveStudentStorageKey = getActiveStudentStorageKey;

