// ==========================================
// ENGINE APLIKASI PAINT TERBARU (MODERN EDITION DENGAN FITUR GESER OBJEK & RAGAM BRUSHES)
// ==========================================
let paintApp = {
  canvas: null,
  ctx: null,
  initialized: false,
  color: '#000000',
  size: 6,
  tool: 'brush', // brush, pencil, eraser, bucket, text, select
  brushType: 'brush', // brush, calligraphy1, calligraphy2, airbrush, oil, crayon, marker, natural_pencil, watercolor
  shape: 'none', // none, line, rect, circle, triangle, diamond, arrow, bubble, star, heart
  isDrawing: false,
  isMovingObject: false,
  startX: 0,
  startY: 0,
  lastX: 0,
  lastY: 0,
  snapshot: null,
  history: [],
  redoList: [],
  activeObject: null // Objek/Bentuk yang sedang aktif dan bisa digeser-geser
};

function initPaintApp() {
  paintApp.canvas = document.getElementById('paint-canvas');
  if (!paintApp.canvas) return;
  paintApp.ctx = paintApp.canvas.getContext('2d', { willReadFrequently: true });

  if (!paintApp.initialized) {
    // Beri latar belakang putih default
    paintApp.ctx.fillStyle = '#ffffff';
    paintApp.ctx.fillRect(0, 0, paintApp.canvas.width, paintApp.canvas.height);
    savePaintState();

    // Mouse Listeners
    paintApp.canvas.addEventListener('mousedown', startPaintDraw);
    paintApp.canvas.addEventListener('mousemove', onPaintDrawMove);
    paintApp.canvas.addEventListener('mouseup', endPaintDraw);
    paintApp.canvas.addEventListener('mouseleave', endPaintDraw);

    // Touch Listeners untuk Tablet / HP
    paintApp.canvas.addEventListener('touchstart', (e) => {
      e.preventDefault();
      startPaintDraw(e);
    }, { passive: false });
    paintApp.canvas.addEventListener('touchmove', (e) => {
      e.preventDefault();
      onPaintDrawMove(e);
    }, { passive: false });
    paintApp.canvas.addEventListener('touchend', (e) => {
      e.preventDefault();
      endPaintDraw(e);
    }, { passive: false });

    // Listener Klik di Luar Popover Brushes untuk Otomatis Menutup Menu
    document.addEventListener('click', (e) => {
      const menu = document.getElementById('paint-brushes-menu');
      const btn = document.getElementById('paint-tool-brush');
      if (menu && !menu.classList.contains('hidden')) {
        if (!menu.contains(e.target) && (!btn || !btn.contains(e.target))) {
          menu.classList.add('hidden');
        }
      }
    });

    // Keyboard Arrow Keys Listener untuk menggeser objek aktif dengan presisi
    window.addEventListener('keydown', (e) => {
      if (!paintApp.activeObject) return;
      const tabPraktik = document.getElementById('tab-praktik');
      if (!tabPraktik || tabPraktik.classList.contains('hidden')) return;
      const areaGambar = document.getElementById('p1-area-gambar');
      if (!areaGambar || areaGambar.classList.contains('hidden')) return;

      const step = e.shiftKey ? 10 : 3;
      if (e.key === 'ArrowLeft') {
        e.preventDefault();
        paintApp.activeObject.x -= step;
        renderActivePaintObject();
      } else if (e.key === 'ArrowRight') {
        e.preventDefault();
        paintApp.activeObject.x += step;
        renderActivePaintObject();
      } else if (e.key === 'ArrowUp') {
        e.preventDefault();
        paintApp.activeObject.y -= step;
        renderActivePaintObject();
      } else if (e.key === 'ArrowDown') {
        e.preventDefault();
        paintApp.activeObject.y += step;
        renderActivePaintObject();
      } else if (e.key === 'Enter' || e.key === 'Escape') {
        e.preventDefault();
        commitActivePaintObject();
      }
    });

    paintApp.initialized = true;
  }
}

function getPaintPointerPos(e) {
  const rect = paintApp.canvas.getBoundingClientRect();
  const scaleX = paintApp.canvas.width / rect.width;
  const scaleY = paintApp.canvas.height / rect.height;

  let clientX = e.clientX;
  let clientY = e.clientY;
  if (clientX === undefined && e.touches && e.touches.length > 0) {
    clientX = e.touches[0].clientX;
    clientY = e.touches[0].clientY;
  } else if (clientX === undefined && e.changedTouches && e.changedTouches.length > 0) {
    clientX = e.changedTouches[0].clientX;
    clientY = e.changedTouches[0].clientY;
  }

  return {
    x: ((clientX !== undefined ? clientX : 0) - rect.left) * scaleX,
    y: ((clientY !== undefined ? clientY : 0) - rect.top) * scaleY
  };
}

// Cek apakah kursor berada di dalam area objek yang sedang digeser
function isPointInActiveObject(pos) {
  if (!paintApp.activeObject) return false;
  const pad = Math.max(10, (paintApp.activeObject.size || 6));
  const obj = paintApp.activeObject;
  return (
    pos.x >= obj.x - pad &&
    pos.x <= obj.x + obj.w + pad &&
    pos.y >= obj.y - pad &&
    pos.y <= obj.y + obj.h + pad
  );
}

// Perbarui tombol "Tempel Objek" dan info status
function updatePaintCommitButton() {
  const btn = document.getElementById('paint-btn-commit');
  const info = document.getElementById('paint-status-obj-info');
  if (paintApp.activeObject) {
    if (btn) btn.classList.remove('hidden');
    if (info) info.classList.remove('hidden');
  } else {
    if (btn) btn.classList.add('hidden');
    if (info) info.classList.add('hidden');
  }
}

// Render objek aktif yang sedang digeser dengan bingkai putus-putus dan penanda
function renderActivePaintObject() {
  if (!paintApp.activeObject || !paintApp.ctx) return;
  const obj = paintApp.activeObject;
  const ctx = paintApp.ctx;

  // 1. Pulihkan kanvas latar belakang bersih
  if (obj.underneathSnapshot) {
    ctx.putImageData(obj.underneathSnapshot, 0, 0);
  }

  // 2. Gambar objek di koordinat (x, y) saat ini
  ctx.save();
  if (obj.type === 'shape') {
    ctx.strokeStyle = obj.color;
    ctx.fillStyle = obj.color;
    ctx.lineWidth = obj.size;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    if (obj.shape === 'rect') {
      ctx.strokeRect(obj.x, obj.y, obj.w, obj.h);
    } else if (obj.shape === 'circle') {
      ctx.beginPath();
      const radius = Math.min(obj.w, obj.h) / 2;
      ctx.arc(obj.x + obj.w / 2, obj.y + obj.h / 2, Math.max(2, radius), 0, 2 * Math.PI);
      ctx.stroke();
    } else if (obj.shape === 'line') {
      ctx.beginPath();
      ctx.moveTo(obj.x, obj.y);
      ctx.lineTo(obj.x + obj.w, obj.y + obj.h);
      ctx.stroke();
    } else if (obj.shape === 'triangle') {
      drawPaintTriangle(obj.x, obj.y, obj.x + obj.w, obj.y + obj.h);
    } else if (obj.shape === 'diamond') {
      drawPaintDiamond(obj.x, obj.y, obj.x + obj.w, obj.y + obj.h);
    } else if (obj.shape === 'arrow') {
      drawPaintArrow(obj.x, obj.y, obj.x + obj.w, obj.y + obj.h);
    } else if (obj.shape === 'bubble') {
      drawPaintBubble(obj.x, obj.y, obj.x + obj.w, obj.y + obj.h);
    } else if (obj.shape === 'star') {
      drawPaintStar(obj.x + obj.w / 2, obj.y + obj.h / 2, obj.x + obj.w / 2, obj.y);
    } else if (obj.shape === 'heart') {
      drawPaintHeart(obj.x, obj.y, obj.x + obj.w, obj.y + obj.h);
    }
  } else if (obj.type === 'selection' && obj.offscreen) {
    ctx.drawImage(obj.offscreen, obj.x, obj.y);
  }
  ctx.restore();

  // 3. Gambar kotak seleksi putus-putus (Dashed Bounding Box)
  ctx.save();
  ctx.setLineDash([6, 4]);
  ctx.strokeStyle = '#2563eb';
  ctx.lineWidth = 2;
  ctx.strokeRect(obj.x - 3, obj.y - 3, obj.w + 6, obj.h + 6);

  // 4 Handle sudut solid biru
  ctx.setLineDash([]);
  ctx.fillStyle = '#2563eb';
  const hs = 7;
  const corners = [
    [obj.x - 3 - hs / 2, obj.y - 3 - hs / 2],
    [obj.x + obj.w + 3 - hs / 2, obj.y - 3 - hs / 2],
    [obj.x - 3 - hs / 2, obj.y + obj.h + 3 - hs / 2],
    [obj.x + obj.w + 3 - hs / 2, obj.y + obj.h + 3 - hs / 2]
  ];
  corners.forEach(([hx, hy]) => {
    ctx.fillRect(hx, hy, hs, hs);
  });

  // 4. Balon petunjuk geser (Floating Hint Badge)
  const badgeText = '✥ Geser Objek (Klik & Drag)';
  ctx.font = 'bold 11px Fredoka, sans-serif';
  const tw = ctx.measureText(badgeText).width;
  const bw = tw + 18;
  const bh = 22;
  const bx = Math.max(4, Math.min(paintApp.canvas.width - bw - 4, obj.x + obj.w / 2 - bw / 2));
  const by = (obj.y - bh - 8 >= 4) ? obj.y - bh - 8 : (obj.y + obj.h + 8);

  ctx.fillStyle = '#1e293b';
  ctx.beginPath();
  if (typeof ctx.roundRect === 'function') {
    ctx.roundRect(bx, by, bw, bh, 8);
  } else {
    ctx.rect(bx, by, bw, bh);
  }
  ctx.fill();

  ctx.fillStyle = '#f8fafc';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(badgeText, bx + bw / 2, by + bh / 2);

  ctx.restore();
  updatePaintCommitButton();
}

// Kunci dan tempel objek aktif ke kanvas secara permanen
function commitActivePaintObject() {
  if (!paintApp.activeObject || !paintApp.ctx) return;
  const obj = paintApp.activeObject;
  const ctx = paintApp.ctx;

  // 1. Pulihkan latar belakang bersih
  if (obj.underneathSnapshot) {
    ctx.putImageData(obj.underneathSnapshot, 0, 0);
  }

  // 2. Gambar secara permanen tanpa kotak seleksi
  ctx.save();
  if (obj.type === 'shape') {
    ctx.strokeStyle = obj.color;
    ctx.fillStyle = obj.color;
    ctx.lineWidth = obj.size;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    if (obj.shape === 'rect') {
      ctx.strokeRect(obj.x, obj.y, obj.w, obj.h);
    } else if (obj.shape === 'circle') {
      ctx.beginPath();
      const radius = Math.min(obj.w, obj.h) / 2;
      ctx.arc(obj.x + obj.w / 2, obj.y + obj.h / 2, Math.max(2, radius), 0, 2 * Math.PI);
      ctx.stroke();
    } else if (obj.shape === 'line') {
      ctx.beginPath();
      ctx.moveTo(obj.x, obj.y);
      ctx.lineTo(obj.x + obj.w, obj.y + obj.h);
      ctx.stroke();
    } else if (obj.shape === 'triangle') {
      drawPaintTriangle(obj.x, obj.y, obj.x + obj.w, obj.y + obj.h);
    } else if (obj.shape === 'diamond') {
      drawPaintDiamond(obj.x, obj.y, obj.x + obj.w, obj.y + obj.h);
    } else if (obj.shape === 'arrow') {
      drawPaintArrow(obj.x, obj.y, obj.x + obj.w, obj.y + obj.h);
    } else if (obj.shape === 'bubble') {
      drawPaintBubble(obj.x, obj.y, obj.x + obj.w, obj.y + obj.h);
    } else if (obj.shape === 'star') {
      drawPaintStar(obj.x + obj.w / 2, obj.y + obj.h / 2, obj.x + obj.w / 2, obj.y);
    } else if (obj.shape === 'heart') {
      drawPaintHeart(obj.x, obj.y, obj.x + obj.w, obj.y + obj.h);
    }
  } else if (obj.type === 'selection' && obj.offscreen) {
    ctx.drawImage(obj.offscreen, obj.x, obj.y);
  }
  ctx.restore();

  paintApp.activeObject = null;
  paintApp.isMovingObject = false;
  savePaintState();
  updatePaintCommitButton();
  playSound('click');
}
window.commitActivePaintObject = commitActivePaintObject;

function startPaintDraw(e) {
  const pos = getPaintPointerPos(e);

  // 1. Jika sedang ada objek aktif yang bisa digeser
  if (paintApp.activeObject) {
    if (isPointInActiveObject(pos)) {
      // Klik di dalam objek -> mulai menggeser!
      paintApp.isMovingObject = true;
      paintApp.isDrawing = false;
      paintApp.activeObject.isDragging = true;
      paintApp.activeObject.dragStartX = pos.x;
      paintApp.activeObject.dragStartY = pos.y;
      paintApp.activeObject.origX = paintApp.activeObject.x;
      paintApp.activeObject.origY = paintApp.activeObject.y;
      paintApp.canvas.style.cursor = 'grabbing';
      return;
    } else {
      // Klik di luar objek -> kunci dan tempel objek tersebut
      commitActivePaintObject();
    }
  }

  // 2. Mode Alat Geser / Seleksi Area (Select & Move)
  if (paintApp.tool === 'select') {
    paintApp.isDrawing = true;
    paintApp.startX = pos.x;
    paintApp.startY = pos.y;
    paintApp.snapshot = paintApp.ctx.getImageData(0, 0, paintApp.canvas.width, paintApp.canvas.height);
    return;
  }

  // 3. Cat Tumpah (Bucket)
  if (paintApp.tool === 'bucket') {
    paintApp.ctx.fillStyle = paintApp.color;
    paintApp.ctx.fillRect(0, 0, paintApp.canvas.width, paintApp.canvas.height);
    savePaintState();
    playSound('click');
    return;
  }

  // 4. Menggambar Bentuk atau Goresan Bebas
  paintApp.isDrawing = true;
  paintApp.startX = pos.x;
  paintApp.startY = pos.y;
  paintApp.lastX = pos.x;
  paintApp.lastY = pos.y;
  paintApp.snapshot = paintApp.ctx.getImageData(0, 0, paintApp.canvas.width, paintApp.canvas.height);

  if (paintApp.shape === 'none') {
    // Mode goresan bebas (ragam kuas, pensil, eraser)
    const brushToUse = (paintApp.tool === 'eraser') ? 'eraser' : (paintApp.tool === 'pencil' ? 'natural_pencil' : paintApp.brushType);
    drawCustomBrushStroke(pos.x, pos.y, pos.x, pos.y, brushToUse);
  }
}

function onPaintDrawMove(e) {
  const pos = getPaintPointerPos(e);

  // A. Jika sedang menggeser objek (Moving Object)
  if (paintApp.isMovingObject && paintApp.activeObject) {
    const dx = pos.x - paintApp.activeObject.dragStartX;
    const dy = pos.y - paintApp.activeObject.dragStartY;
    paintApp.activeObject.x = Math.round(paintApp.activeObject.origX + dx);
    paintApp.activeObject.y = Math.round(paintApp.activeObject.origY + dy);
    renderActivePaintObject();
    return;
  }

  // B. Hover di atas objek aktif saat santai (tidak sedang menekan mouse)
  if (!paintApp.isDrawing && paintApp.activeObject) {
    if (isPointInActiveObject(pos)) {
      paintApp.canvas.style.cursor = 'move';
    } else {
      paintApp.canvas.style.cursor = (paintApp.tool === 'select') ? 'crosshair' : 'default';
    }
    return;
  }

  // C. Jika sedang tidak menggambar, hentikan
  if (!paintApp.isDrawing) return;

  // C1. Mode Seleksi Marquee
  if (paintApp.tool === 'select') {
    paintApp.ctx.putImageData(paintApp.snapshot, 0, 0);
    paintApp.ctx.save();
    paintApp.ctx.setLineDash([6, 4]);
    paintApp.ctx.strokeStyle = '#2563eb';
    paintApp.ctx.lineWidth = 1.5;
    const w = pos.x - paintApp.startX;
    const h = pos.y - paintApp.startY;
    paintApp.ctx.strokeRect(paintApp.startX, paintApp.startY, w, h);
    paintApp.ctx.restore();
    return;
  }

  // C2. Mode Goresan Bebas dengan Engine Brushes Berinterpolasi Mulus
  if (paintApp.shape === 'none') {
    const brushToUse = (paintApp.tool === 'eraser') ? 'eraser' : (paintApp.tool === 'pencil' ? 'natural_pencil' : paintApp.brushType);
    drawCustomBrushStroke(paintApp.lastX, paintApp.lastY, pos.x, pos.y, brushToUse);
    paintApp.lastX = pos.x;
    paintApp.lastY = pos.y;
    return;
  }

  // C3. Mode Gambar Bentuk (Rectangle, Circle, Triangle, Diamond, Arrow, Bubble, Star, Heart, Line)
  paintApp.ctx.putImageData(paintApp.snapshot, 0, 0);
  paintApp.ctx.strokeStyle = paintApp.color;
  paintApp.ctx.lineWidth = paintApp.size;
  paintApp.ctx.fillStyle = paintApp.color;

  const sx = paintApp.startX;
  const sy = paintApp.startY;
  const ex = pos.x;
  const ey = pos.y;
  const w = ex - sx;
  const h = ey - sy;

  if (paintApp.shape === 'line') {
    paintApp.ctx.beginPath();
    paintApp.ctx.moveTo(sx, sy);
    paintApp.ctx.lineTo(ex, ey);
    paintApp.ctx.stroke();
  } else if (paintApp.shape === 'rect') {
    paintApp.ctx.strokeRect(sx, sy, w, h);
  } else if (paintApp.shape === 'circle') {
    paintApp.ctx.beginPath();
    const radius = Math.sqrt(w * w + h * h) / 2;
    const cx = (sx + ex) / 2;
    const cy = (sy + ey) / 2;
    paintApp.ctx.arc(cx, cy, Math.max(2, radius), 0, 2 * Math.PI);
    paintApp.ctx.stroke();
  } else if (paintApp.shape === 'triangle') {
    drawPaintTriangle(sx, sy, ex, ey);
  } else if (paintApp.shape === 'diamond') {
    drawPaintDiamond(sx, sy, ex, ey);
  } else if (paintApp.shape === 'arrow') {
    drawPaintArrow(sx, sy, ex, ey);
  } else if (paintApp.shape === 'bubble') {
    drawPaintBubble(sx, sy, ex, ey);
  } else if (paintApp.shape === 'star') {
    drawPaintStar(sx, sy, ex, ey);
  } else if (paintApp.shape === 'heart') {
    drawPaintHeart(sx, sy, ex, ey);
  }
}

function endPaintDraw(e) {
  // 1. Selesai menggeser objek
  if (paintApp.isMovingObject) {
    paintApp.isMovingObject = false;
    if (paintApp.activeObject) {
      paintApp.activeObject.isDragging = false;
      renderActivePaintObject();
    }
    paintApp.canvas.style.cursor = 'move';
    return;
  }

  if (!paintApp.isDrawing) return;
  paintApp.isDrawing = false;
  const pos = getPaintPointerPos(e);
  const sx = paintApp.startX;
  const sy = paintApp.startY;
  const ex = pos.x;
  const ey = pos.y;
  const w = ex - sx;
  const h = ey - sy;

  // 2. Selesai membuat seleksi (Tool 'select')
  if (paintApp.tool === 'select') {
    if (Math.abs(w) > 6 && Math.abs(h) > 6) {
      const selX = Math.round(Math.min(sx, ex));
      const selY = Math.round(Math.min(sy, ey));
      const selW = Math.round(Math.abs(w));
      const selH = Math.round(Math.abs(h));

      // Kembalikan kanvas sebelum garis putus-putus
      paintApp.ctx.putImageData(paintApp.snapshot, 0, 0);

      // Angkat pixel area seleksi ke kanvas pembantu
      const offCanvas = document.createElement('canvas');
      offCanvas.width = selW;
      offCanvas.height = selH;
      const offCtx = offCanvas.getContext('2d');
      const imgData = paintApp.ctx.getImageData(selX, selY, selW, selH);
      offCtx.putImageData(imgData, 0, 0);

      // Isi area asal dengan warna putih
      paintApp.ctx.fillStyle = '#ffffff';
      paintApp.ctx.fillRect(selX, selY, selW, selH);

      // Ambil snapshot background dasar
      const underneath = paintApp.ctx.getImageData(0, 0, paintApp.canvas.width, paintApp.canvas.height);

      paintApp.activeObject = {
        type: 'selection',
        offscreen: offCanvas,
        x: selX,
        y: selY,
        w: selW,
        h: selH,
        underneathSnapshot: underneath,
        isDragging: false
      };
      renderActivePaintObject();
      playSound('success');
      showToast('Area terpilih! Klik & geser objek ini ke posisi yang kamu inginkan ✥', 'success');
    } else {
      paintApp.ctx.putImageData(paintApp.snapshot, 0, 0);
    }
    return;
  }

  // 3. Selesai menggambar bentuk (Rectangle, Circle, Star, Heart, Line)
  if (paintApp.shape !== 'none') {
    if (Math.abs(w) > 4 || Math.abs(h) > 4) {
      const objX = Math.round(Math.min(sx, ex));
      const objY = Math.round(Math.min(sy, ey));
      const objW = Math.round(Math.abs(w));
      const objH = Math.round(Math.abs(h));

      paintApp.activeObject = {
        type: 'shape',
        shape: paintApp.shape,
        color: paintApp.color,
        size: paintApp.size,
        x: objX,
        y: objY,
        w: objW,
        h: objH,
        underneathSnapshot: paintApp.snapshot,
        isDragging: false
      };
      renderActivePaintObject();
      playSound('success');
      showToast('Bentuk dibuat! Kamu bisa klik & geser untuk memindahkan posisinya ✥', 'success');
    } else {
      paintApp.ctx.putImageData(paintApp.snapshot, 0, 0);
    }
    return;
  }

  // 4. Goresan bebas normal -> simpan langsung ke riwayat undo
  paintApp.ctx.beginPath();
  savePaintState();
}

// Menggambar Bentuk Bintang
function drawPaintStar(cx, cy, ex, ey) {
  const r = Math.sqrt((ex - cx) * (ex - cx) + (ey - cy) * (ey - cy));
  if (r < 4) return;
  const spikes = 5;
  const step = Math.PI / spikes;
  let rot = Math.PI / 2 * 3;
  let x = cx;
  let y = cy;

  paintApp.ctx.beginPath();
  paintApp.ctx.moveTo(cx, cy - r);
  for (let i = 0; i < spikes; i++) {
    x = cx + Math.cos(rot) * r;
    y = cy + Math.sin(rot) * r;
    paintApp.ctx.lineTo(x, y);
    rot += step;

    x = cx + Math.cos(rot) * (r / 2);
    y = cy + Math.sin(rot) * (r / 2);
    paintApp.ctx.lineTo(x, y);
    rot += step;
  }
  paintApp.ctx.lineTo(cx, cy - r);
  paintApp.ctx.closePath();
  paintApp.ctx.stroke();
}

// Menggambar Bentuk Hati
function drawPaintHeart(sx, sy, ex, ey) {
  const w = ex - sx;
  const h = ey - sy;
  if (Math.abs(w) < 4 || Math.abs(h) < 4) return;

  const topCurveHeight = h * 0.3;
  paintApp.ctx.beginPath();
  paintApp.ctx.moveTo(sx + w / 2, sy + topCurveHeight);
  paintApp.ctx.bezierCurveTo(sx + w / 2, sy, sx, sy, sx, sy + topCurveHeight);
  paintApp.ctx.bezierCurveTo(sx, sy + (h + topCurveHeight) / 2, sx + w / 2, sy + (h + topCurveHeight) / 2, sx + w / 2, sy + h);
  paintApp.ctx.bezierCurveTo(sx + w / 2, sy + (h + topCurveHeight) / 2, sx + w, sy + (h + topCurveHeight) / 2, sx + w, sy + topCurveHeight);
  paintApp.ctx.bezierCurveTo(sx + w, sy, sx + w / 2, sy, sx + w / 2, sy + topCurveHeight);
  paintApp.ctx.closePath();
  paintApp.ctx.stroke();
}

// Menggambar Bentuk Segitiga (Triangle)
function drawPaintTriangle(sx, sy, ex, ey) {
  const minX = Math.min(sx, ex);
  const maxX = Math.max(sx, ex);
  const minY = Math.min(sy, ey);
  const maxY = Math.max(sy, ey);
  paintApp.ctx.beginPath();
  paintApp.ctx.moveTo((minX + maxX) / 2, minY);
  paintApp.ctx.lineTo(maxX, maxY);
  paintApp.ctx.lineTo(minX, maxY);
  paintApp.ctx.closePath();
  paintApp.ctx.stroke();
}
window.drawPaintTriangle = drawPaintTriangle;

// Menggambar Bentuk Belah Ketupat (Diamond)
function drawPaintDiamond(sx, sy, ex, ey) {
  const minX = Math.min(sx, ex);
  const maxX = Math.max(sx, ex);
  const minY = Math.min(sy, ey);
  const maxY = Math.max(sy, ey);
  const cx = (minX + maxX) / 2;
  const cy = (minY + maxY) / 2;
  paintApp.ctx.beginPath();
  paintApp.ctx.moveTo(cx, minY);
  paintApp.ctx.lineTo(maxX, cy);
  paintApp.ctx.lineTo(cx, maxY);
  paintApp.ctx.lineTo(minX, cy);
  paintApp.ctx.closePath();
  paintApp.ctx.stroke();
}
window.drawPaintDiamond = drawPaintDiamond;

// Menggambar Bentuk Panah Kanan (Right Arrow)
function drawPaintArrow(sx, sy, ex, ey) {
  const minX = Math.min(sx, ex);
  const maxX = Math.max(sx, ex);
  const minY = Math.min(sy, ey);
  const maxY = Math.max(sy, ey);
  const w = maxX - minX;
  const h = maxY - minY;
  if (w < 6 || h < 6) return;

  const stemTop = minY + h * 0.3;
  const stemBottom = minY + h * 0.7;
  const headStart = minX + w * 0.6;

  paintApp.ctx.beginPath();
  paintApp.ctx.moveTo(minX, stemTop);
  paintApp.ctx.lineTo(headStart, stemTop);
  paintApp.ctx.lineTo(headStart, minY);
  paintApp.ctx.lineTo(maxX, minY + h * 0.5);
  paintApp.ctx.lineTo(headStart, maxY);
  paintApp.ctx.lineTo(headStart, stemBottom);
  paintApp.ctx.lineTo(minX, stemBottom);
  paintApp.ctx.closePath();
  paintApp.ctx.stroke();
}
window.drawPaintArrow = drawPaintArrow;

// Menggambar Bentuk Balon Percakapan (Speech Bubble / Callout)
function drawPaintBubble(sx, sy, ex, ey) {
  const minX = Math.min(sx, ex);
  const maxX = Math.max(sx, ex);
  const minY = Math.min(sy, ey);
  const maxY = Math.max(sy, ey);
  const w = maxX - minX;
  const h = maxY - minY;
  if (w < 8 || h < 8) return;

  const bodyH = h * 0.72;
  const bottomBodyY = minY + bodyH;
  const r = Math.min(14, w * 0.2, bodyH * 0.3);

  paintApp.ctx.beginPath();
  paintApp.ctx.moveTo(minX + r, minY);
  paintApp.ctx.lineTo(maxX - r, minY);
  paintApp.ctx.quadraticCurveTo(maxX, minY, maxX, minY + r);
  paintApp.ctx.lineTo(maxX, bottomBodyY - r);
  paintApp.ctx.quadraticCurveTo(maxX, bottomBodyY, maxX - r, bottomBodyY);
  // Pointer tail ke bawah kiri
  paintApp.ctx.lineTo(minX + w * 0.45, bottomBodyY);
  paintApp.ctx.lineTo(minX + w * 0.15, maxY);
  paintApp.ctx.lineTo(minX + w * 0.25, bottomBodyY);
  paintApp.ctx.lineTo(minX + r, bottomBodyY);
  paintApp.ctx.quadraticCurveTo(minX, bottomBodyY, minX, bottomBodyY - r);
  paintApp.ctx.lineTo(minX, minY + r);
  paintApp.ctx.quadraticCurveTo(minX, minY, minX + r, minY);
  paintApp.ctx.closePath();
  paintApp.ctx.stroke();
}
window.drawPaintBubble = drawPaintBubble;

// ========================================================
// RAGAM BRUSHES CANVAS RENDERING ENGINE (9 JENIS KUAS RESMI)
// ========================================================
function drawCustomBrushStroke(fromX, fromY, toX, toY, brushType) {
  const ctx = paintApp.ctx;
  if (!ctx) return;

  const dx = toX - fromX;
  const dy = toY - fromY;
  const dist = Math.hypot(dx, dy);
  const color = (brushType === 'eraser' || paintApp.tool === 'eraser') ? '#ffffff' : paintApp.color;
  const baseSize = (brushType === 'eraser' || paintApp.tool === 'eraser') 
    ? paintApp.size * 2 
    : (paintApp.tool === 'pencil' ? Math.max(2, Math.round(paintApp.size / 3)) : paintApp.size);

  ctx.save();
  ctx.fillStyle = color;
  ctx.strokeStyle = color;

  // 1. KUAS STANDAR (Brush) - Solid smooth round line
  if (brushType === 'brush' || brushType === 'eraser') {
    ctx.lineWidth = baseSize;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';
    ctx.beginPath();
    ctx.moveTo(fromX, fromY);
    ctx.lineTo(toX, toY);
    ctx.stroke();
  }
  // 2. KUAS KALIGRAFI 1 (Calligraphy Brush) - 45° angled ribbon
  else if (brushType === 'calligraphy1') {
    const steps = Math.max(1, Math.ceil(dist / 2));
    const ribbonHalf = baseSize * 0.9;
    const cos45 = Math.SQRT1_2;
    const sin45 = Math.SQRT1_2;
    const offX = ribbonHalf * cos45;
    const offY = -ribbonHalf * sin45;

    ctx.lineWidth = 2.5;
    for (let i = 0; i <= steps; i++) {
      const t = steps === 0 ? 0 : i / steps;
      const curX = fromX + dx * t;
      const curY = fromY + dy * t;
      ctx.beginPath();
      ctx.moveTo(curX - offX, curY - offY);
      ctx.lineTo(curX + offX, curY + offY);
      ctx.stroke();
    }
  }
  // 3. PENA KALIGRAFI 2 (Calligraphy Pen) - -45° blade angle
  else if (brushType === 'calligraphy2') {
    const steps = Math.max(1, Math.ceil(dist / 2));
    const ribbonHalf = baseSize * 0.85;
    const cosM45 = Math.SQRT1_2;
    const sinM45 = -Math.SQRT1_2;
    const offX = ribbonHalf * cosM45;
    const offY = -ribbonHalf * sinM45;

    ctx.lineWidth = 2;
    for (let i = 0; i <= steps; i++) {
      const t = steps === 0 ? 0 : i / steps;
      const curX = fromX + dx * t;
      const curY = fromY + dy * t;
      ctx.beginPath();
      ctx.moveTo(curX - offX, curY - offY);
      ctx.lineTo(curX + offX, curY + offY);
      ctx.stroke();
    }
  }
  // 4. CAT SEMPROT (Airbrush) - Aerosol speckle dispersion
  else if (brushType === 'airbrush') {
    const radius = Math.max(8, baseSize * 1.5);
    const density = Math.max(6, Math.floor(baseSize * 1.6));
    const steps = Math.max(1, Math.ceil(dist / 4));

    ctx.globalAlpha = 0.35;
    for (let s = 0; s <= steps; s++) {
      const t = steps === 0 ? 0 : s / steps;
      const curX = fromX + dx * t;
      const curY = fromY + dy * t;
      for (let i = 0; i < density; i++) {
        const angle = Math.random() * Math.PI * 2;
        const r = Math.random() * radius;
        const dotX = curX + Math.cos(angle) * r;
        const dotY = curY + Math.sin(angle) * r;
        const dotSize = Math.random() * 1.8 + 0.8;
        ctx.beginPath();
        ctx.arc(dotX, dotY, dotSize / 2, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }
  // 5. KUAS CAT MINYAK (Oil Brush) - Multi-bristle textured stroke
  else if (brushType === 'oil') {
    const steps = Math.max(1, Math.ceil(dist / 3));
    const bristles = [-0.8, -0.4, 0, 0.4, 0.8];
    const bristleSize = Math.max(1.8, baseSize * 0.35);

    let nx = 0, ny = 0;
    if (dist > 0.001) {
      nx = -dy / dist;
      ny = dx / dist;
    } else {
      nx = 0;
      ny = 1;
    }

    for (let i = 0; i <= steps; i++) {
      const t = steps === 0 ? 0 : i / steps;
      const curX = fromX + dx * t;
      const curY = fromY + dy * t;

      bristles.forEach((bOffset, bIdx) => {
        const jitter = (Math.random() - 0.5) * 1.5;
        const spread = (baseSize * 0.7 * bOffset) + jitter;
        const bx = curX + nx * spread;
        const by = curY + ny * spread;
        ctx.globalAlpha = 0.55 + ((bIdx % 2) * 0.25);
        ctx.beginPath();
        ctx.arc(bx, by, bristleSize / 2, 0, Math.PI * 2);
        ctx.fill();
      });
    }
  }
  // 6. KRAYON LILIN (Crayon) - Wax textured porous stroke
  else if (brushType === 'crayon') {
    const steps = Math.max(1, Math.ceil(dist / 2.5));
    const crayonRadius = Math.max(3, baseSize * 0.65);

    for (let i = 0; i <= steps; i++) {
      const t = steps === 0 ? 0 : i / steps;
      const curX = fromX + dx * t;
      const curY = fromY + dy * t;

      ctx.globalAlpha = 0.5;
      ctx.beginPath();
      ctx.arc(curX, curY, crayonRadius, 0, Math.PI * 2);
      ctx.fill();

      ctx.globalAlpha = 0.8;
      const flecks = Math.max(3, Math.floor(baseSize * 0.8));
      for (let f = 0; f < flecks; f++) {
        const fx = curX + (Math.random() - 0.5) * crayonRadius * 2;
        const fy = curY + (Math.random() - 0.5) * crayonRadius * 2;
        ctx.fillRect(fx, fy, 1.6, 1.6);
      }
    }
  }
  // 7. SPIDOL / STABILO (Marker) - Flat broad translucent nib
  else if (brushType === 'marker') {
    ctx.globalAlpha = 0.42;
    ctx.lineWidth = Math.max(8, baseSize * 1.5);
    ctx.lineCap = 'square';
    ctx.lineJoin = 'miter';
    ctx.beginPath();
    ctx.moveTo(fromX, fromY);
    ctx.lineTo(toX, toY);
    ctx.stroke();
  }
  // 8. PENSIL ALAMI (Natural Pencil) - Fine granular graphite sketch
  else if (brushType === 'natural_pencil') {
    const pencilWidth = Math.max(1.5, Math.min(4, baseSize * 0.35));
    ctx.globalAlpha = 0.75;
    ctx.lineWidth = pencilWidth;
    ctx.lineCap = 'round';
    ctx.beginPath();
    ctx.moveTo(fromX, fromY);
    ctx.lineTo(toX, toY);
    ctx.stroke();

    if (dist > 1) {
      const steps = Math.max(1, Math.ceil(dist / 3));
      ctx.globalAlpha = 0.45;
      for (let i = 0; i <= steps; i++) {
        const t = steps === 0 ? 0 : i / steps;
        const gx = fromX + dx * t + (Math.random() - 0.5) * 2;
        const gy = fromY + dy * t + (Math.random() - 0.5) * 2;
        ctx.fillRect(gx, gy, 1, 1);
      }
    }
  }
  // 9. KUAS CAT AIR (Watercolour Brush) - Soft translucent feather wash
  else if (brushType === 'watercolor') {
    const steps = Math.max(1, Math.ceil(dist / 3.5));
    const washRadius = Math.max(6, baseSize * 1.3);

    for (let i = 0; i <= steps; i++) {
      const t = steps === 0 ? 0 : i / steps;
      const curX = fromX + dx * t;
      const curY = fromY + dy * t;

      ctx.globalAlpha = 0.12;
      ctx.beginPath();
      ctx.arc(curX, curY, washRadius, 0, Math.PI * 2);
      ctx.fill();

      ctx.globalAlpha = 0.16;
      ctx.beginPath();
      ctx.arc(curX + (Math.random() - 0.5) * 2, curY + (Math.random() - 0.5) * 2, washRadius * 0.6, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  ctx.restore();
}
window.drawCustomBrushStroke = drawCustomBrushStroke;

// Toggle Popover Ragam Kuas
function togglePaintBrushesMenu(e) {
  if (e) e.stopPropagation();
  playSound('click');
  const menu = document.getElementById('paint-brushes-menu');
  if (!menu) return;
  menu.classList.toggle('hidden');
}
window.togglePaintBrushesMenu = togglePaintBrushesMenu;

// Memilih Salah Satu dari 9 Ragam Kuas
function selectPaintBrush(brushType) {
  playSound('click');
  paintApp.brushType = brushType;
  setPaintTool('brush');

  // Tutup dropdown menu popover
  const menu = document.getElementById('paint-brushes-menu');
  if (menu) menu.classList.add('hidden');

  // Metadata visual untuk 9 Kuas Windows 11 Paint
  const brushMeta = {
    brush: { label: 'Kuas', icon: 'fa-paintbrush', color: 'text-pink-500' },
    calligraphy1: { label: 'Kaligrafi 1', icon: 'fa-pen-nib', color: 'text-indigo-600' },
    calligraphy2: { label: 'Kaligrafi 2', icon: 'fa-feather-pointed', color: 'text-violet-600' },
    airbrush: { label: 'Airbrush', icon: 'fa-spray-can', color: 'text-emerald-600' },
    oil: { label: 'Cat Minyak', icon: 'fa-brush', color: 'text-amber-700' },
    crayon: { label: 'Krayon', icon: 'fa-pencil', color: 'text-orange-600' },
    marker: { label: 'Spidol', icon: 'fa-highlighter', color: 'text-yellow-600' },
    natural_pencil: { label: 'Pensil Alami', icon: 'fa-pen', color: 'text-blue-600' },
    watercolor: { label: 'Cat Air', icon: 'fa-droplet', color: 'text-sky-500' }
  };

  const meta = brushMeta[brushType] || brushMeta.brush;
  const iconEl = document.getElementById('paint-brush-icon');
  const labelEl = document.getElementById('paint-brush-label');
  const statusEl = document.getElementById('paint-status-tool');

  if (iconEl) iconEl.className = `fa-solid ${meta.icon} ${meta.color}`;
  if (labelEl) labelEl.innerText = meta.label;
  if (statusEl) statusEl.innerText = meta.label;

  // Berikan highlight aktif pada item yang dipilih di dalam dropdown
  const brushKeys = ['brush', 'calligraphy1', 'calligraphy2', 'airbrush', 'oil', 'crayon', 'marker', 'natural_pencil', 'watercolor'];
  brushKeys.forEach(k => {
    const optBtn = document.getElementById(`paint-brush-opt-${k}`);
    if (optBtn) {
      if (k === brushType) {
        optBtn.className = 'w-full px-2.5 py-1.5 rounded-xl text-left text-xs font-bold flex items-center justify-between transition border cursor-pointer bg-pink-100/70 border-pink-300';
      } else {
        optBtn.className = 'w-full px-2.5 py-1.5 rounded-xl text-left text-xs font-bold flex items-center justify-between hover:bg-slate-100 transition border border-transparent hover:border-slate-200 cursor-pointer';
      }
    }
  });

  showToast(`Kuas diubah ke: ${meta.label} 🎨`, 'info');
}
window.selectPaintBrush = selectPaintBrush;

// Pengaturan Tool, Shape, Size, dan Color Paint
function setPaintTool(toolName) {
  playSound('click');
  // Jika sedang ada objek aktif dan pengguna memilih alat lain selain 'select', commit objek
  if (paintApp.activeObject && toolName !== 'select') {
    commitActivePaintObject();
  }

  paintApp.tool = toolName;

  // Jika memilih alat 'select', matikan bentuk aktif agar bisa menyeleksi bebas
  if (toolName === 'select') {
    setPaintShape('none');
  }

  const tools = ['brush', 'pencil', 'eraser', 'bucket', 'text', 'select'];
  tools.forEach(t => {
    const btn = document.getElementById(`paint-tool-${t}`);
    if (btn) {
      if (t === toolName) {
        btn.className = 'paint-tool-btn active-paint-tool px-2.5 py-1.5 rounded-xl font-bold flex items-center gap-1.5';
      } else {
        btn.className = 'paint-tool-btn px-2.5 py-1.5 rounded-xl font-bold flex items-center gap-1.5 bg-slate-100 hover:bg-slate-200';
      }
    }
  });

  const toolLabels = { brush: 'Kuas', pencil: 'Pensil', eraser: 'Penghapus', bucket: 'Cat Tumpah', text: 'Teks', select: 'Geser / Seleksi ✥' };
  const labelEl = document.getElementById('paint-status-tool');
  if (labelEl) {
    if (toolName === 'brush') {
      const brushLabels = {
        brush: 'Kuas',
        calligraphy1: 'Kaligrafi 1',
        calligraphy2: 'Kaligrafi 2',
        airbrush: 'Airbrush',
        oil: 'Cat Minyak',
        crayon: 'Krayon',
        marker: 'Spidol',
        natural_pencil: 'Pensil Alami',
        watercolor: 'Cat Air'
      };
      labelEl.innerText = brushLabels[paintApp.brushType] || 'Kuas';
    } else {
      labelEl.innerText = toolLabels[toolName] || toolName;
    }
  }

  if (toolName === 'eraser') {
    paintApp.canvas.style.cursor = 'cell';
  } else if (toolName === 'bucket') {
    paintApp.canvas.style.cursor = 'copy';
  } else if (toolName === 'select') {
    paintApp.canvas.style.cursor = paintApp.activeObject ? 'move' : 'crosshair';
  } else {
    paintApp.canvas.style.cursor = 'crosshair';
  }
}

function setPaintShape(shapeName) {
  playSound('click');
  // Jika sedang ada objek aktif dan pengguna memilih bentuk baru, commit objek sebelumnya
  if (paintApp.activeObject) {
    commitActivePaintObject();
  }

  paintApp.shape = shapeName;

  // Jika memilih bentuk, kembalikan alat dari seleksi ke kuas
  if (shapeName !== 'none' && paintApp.tool === 'select') {
    setPaintTool('brush');
  }

  const shapes = ['none', 'line', 'rect', 'circle', 'triangle', 'diamond', 'arrow', 'bubble', 'star', 'heart'];
  shapes.forEach(s => {
    const btn = document.getElementById(`paint-shape-${s}`);
    if (btn) {
      if (s === shapeName) {
        btn.className = 'paint-shape-btn active-paint-shape px-2 py-1.5 rounded-xl font-bold text-xs';
      } else {
        btn.className = 'paint-shape-btn px-2 py-1.5 rounded-xl font-bold text-xs bg-slate-100 hover:bg-slate-200';
      }
    }
  });
}

function setPaintSize(sizeVal) {
  playSound('click');
  paintApp.size = sizeVal;

  [2, 6, 14, 28].forEach(sz => {
    const btn = document.getElementById(`paint-size-${sz}`);
    if (btn) {
      if (sz === sizeVal) {
        btn.className = 'paint-size-btn active-paint-size w-7 h-7 rounded-lg border font-bold flex items-center justify-center text-xs bg-blue-100 border-blue-400 text-blue-700';
      } else {
        btn.className = 'paint-size-btn w-7 h-7 rounded-lg border font-bold flex items-center justify-center text-xs bg-white text-slate-700';
      }
    }
  });

  const sizeEl = document.getElementById('paint-status-size');
  if (sizeEl) sizeEl.innerText = `${sizeVal}px`;

  // Jika sedang ada bentuk aktif yang belum ditempel, perbarui ketebalannya seketika!
  if (paintApp.activeObject && paintApp.activeObject.type === 'shape') {
    paintApp.activeObject.size = sizeVal;
    renderActivePaintObject();
  }
}

function setPaintColor(colorHex) {
  playSound('click');
  paintApp.color = colorHex;
  const indicator = document.getElementById('paint-active-color-indicator');
  if (indicator) indicator.style.backgroundColor = colorHex;

  const colorInput = document.getElementById('paint-custom-color');
  if (colorInput) colorInput.value = colorHex;

  // Jika sedang ada bentuk aktif yang belum ditempel, perbarui warnanya seketika!
  if (paintApp.activeObject && paintApp.activeObject.type === 'shape') {
    paintApp.activeObject.color = colorHex;
    renderActivePaintObject();
  }
}

window.setPaintTool = setPaintTool;
window.setPaintShape = setPaintShape;
window.setPaintSize = setPaintSize;
window.setPaintColor = setPaintColor;
window.selectPaintBrush = selectPaintBrush;
window.togglePaintBrushesMenu = togglePaintBrushesMenu;
window.drawCustomBrushStroke = drawCustomBrushStroke;
window.drawPaintTriangle = drawPaintTriangle;
window.drawPaintDiamond = drawPaintDiamond;
window.drawPaintArrow = drawPaintArrow;
window.drawPaintBubble = drawPaintBubble;

// Undo, Redo, Clear
function savePaintState() {
  if (!paintApp.canvas) return;
  const data = paintApp.canvas.toDataURL();
  paintApp.history.push(data);
  if (paintApp.history.length > 25) paintApp.history.shift();
  paintApp.redoList = [];
}

function undoPaintCanvas() {
  if (paintApp.activeObject) {
    paintApp.activeObject = null;
    updatePaintCommitButton();
  }
  if (paintApp.history.length > 1) {
    playSound('click');
    const current = paintApp.history.pop();
    paintApp.redoList.push(current);
    const prevState = paintApp.history[paintApp.history.length - 1];
    restorePaintState(prevState);
    showToast('Langkah lukisan dibatalkan (Undo)');
  }
}

function redoPaintCanvas() {
  if (paintApp.activeObject) {
    paintApp.activeObject = null;
    updatePaintCommitButton();
  }
  if (paintApp.redoList.length > 0) {
    playSound('click');
    const nextState = paintApp.redoList.pop();
    paintApp.history.push(nextState);
    restorePaintState(nextState);
    showToast('Langkah lukisan dimajukan (Redo)');
  }
}

function restorePaintState(dataUrl) {
  const img = new Image();
  img.onload = () => {
    paintApp.ctx.clearRect(0, 0, paintApp.canvas.width, paintApp.canvas.height);
    paintApp.ctx.drawImage(img, 0, 0);
  };
  img.src = dataUrl;
}

function clearPaintCanvas() {
  playSound('click');
  if (confirm('Kosongkan lembar kanvas Paint dan mulai lukisan baru?')) {
    if (paintApp.activeObject) {
      paintApp.activeObject = null;
      updatePaintCommitButton();
    }
    paintApp.ctx.fillStyle = '#ffffff';
    paintApp.ctx.fillRect(0, 0, paintApp.canvas.width, paintApp.canvas.height);
    savePaintState();
    showToast('Kanvas Paint telah dibersihkan!');
  }
}

function tambahTeksKePaintPrompt() {
  playSound('click');
  if (paintApp.activeObject) {
    commitActivePaintObject();
  }
  const userText = prompt('Ketik kata atau kalimat yang ingin ditempel ke lukisan:', 'CINTAI ALAM');
  if (userText && userText.trim()) {
    paintApp.ctx.fillStyle = paintApp.color;
    paintApp.ctx.font = 'bold 28px Fredoka, sans-serif';
    paintApp.ctx.fillText(userText.trim(), paintApp.canvas.width / 2 - 80, paintApp.canvas.height / 2);
    savePaintState();
    showToast('Teks berhasil ditempel ke lukisan!');
  }
}

