function toggleLihatPinGuru() {
  const input = document.getElementById('input-pin-guru');
  const icon = document.getElementById('icon-lihat-pin');
  if (!input) return;
  if (input.type === 'password') {
    input.type = 'text';
    if (icon) icon.className = 'fa-solid fa-eye-slash';
  } else {
    input.type = 'password';
    if (icon) icon.className = 'fa-solid fa-eye';
  }
}

function tekanKeypadGuru(char) {
  playSound('click');
  const err = document.getElementById('pesan-error-pin');
  if (err) err.classList.add('hidden');
  const input = document.getElementById('input-pin-guru');
  if (input && input.value.length < 6) {
    input.value += char;
  }
}

function hapusKeypadGuru() {
  playSound('click');
  const err = document.getElementById('pesan-error-pin');
  if (err) err.classList.add('hidden');
  const input = document.getElementById('input-pin-guru');
  if (input && input.value.length > 0) {
    input.value = input.value.slice(0, -1);
  }
}

function verifikasiPinGuru() {
  const input = document.getElementById('input-pin-guru');
  const errorMsg = document.getElementById('pesan-error-pin');
  const enteredPin = input ? input.value.trim() : '';
  const storedPin = getTeacherPin();

  if (!enteredPin) {
    playSound('error');
    if (errorMsg) {
      errorMsg.innerHTML = '<i class="fa-solid fa-circle-exclamation"></i> Masukkan PIN terlebih dahulu!';
      errorMsg.classList.remove('hidden');
    }
    if (input) {
      input.classList.add('border-rose-500', 'animate-shake');
      setTimeout(() => input.classList.remove('animate-shake', 'border-rose-500'), 500);
      input.focus();
    }
    showToast('⚠️ Masukkan PIN Guru terlebih dahulu!', 'warning');
    return;
  }

  // Master Recovery Override: PIN 003734 atau 1234 selalu dapat membuka Dasbor Guru agar guru tidak pernah terkunci
  const isMasterOverride = (enteredPin === DEFAULT_GURU_PIN || enteredPin === '003734' || enteredPin === '1234');
  const isCustomMatch = (enteredPin === storedPin);

  if (isCustomMatch || isMasterOverride) {
    try { playSound('success'); } catch (e) {}
    if (errorMsg) errorMsg.classList.add('hidden');
    state.isGuruLoggedIn = true;
    if (typeof setTeacherSessionActive === 'function') {
      setTeacherSessionActive(true); // Persistensi sesi guru di localStorage, sessionStorage, cookie
    }

    // Jika guru masuk menggunakan Master Override sementara PIN kustom tidak cocok, pulihkan PIN ke default
    if (isMasterOverride && !isCustomMatch) {
      clearTeacherPin();
      perbaruiTampilanStatusPinGuru();
      showToast('🔑 Akses Master Terverifikasi! PIN Dasbor Guru aktif.', 'info');
    }

    tutupModalLoginGuru();
    setHeaderNavMode('guru');
    switchTab('guru');
    var tabB = document.getElementById('tab-beranda');
    var tabG = document.getElementById('tab-guru');
    if (tabB) { tabB.classList.add('hidden'); tabB.style.setProperty('display', 'none', 'important'); }
    if (tabG) { tabG.classList.remove('hidden'); tabG.style.removeProperty('display'); tabG.style.setProperty('display', 'block', 'important'); }
    if (typeof pilihKelasGuruNav === 'function') {
      pilihKelasGuruNav('4');
    }
    if (typeof renderDasborGuru === 'function') {
      renderDasborGuru();
    }
    showToast('Akses Guru Terverifikasi! Selamat datang Ibu Darningsih, S.T. 👩‍🏫', 'success');
  } else {
    try { playSound('error'); } catch (e) {}
    if (errorMsg) {
      errorMsg.innerHTML = '<i class="fa-solid fa-circle-xmark"></i> PIN salah! Akses dasbor guru ditolak.';
      errorMsg.classList.remove('hidden');
    }
    if (input) {
      input.classList.add('border-rose-500', 'animate-shake');
      setTimeout(() => input.classList.remove('animate-shake', 'border-rose-500'), 500);
      input.value = '';
      input.focus();
    }
    showToast('❌ PIN Guru salah! Akses dasbor ditolak.', 'error');
  }
}
window.verifikasiPinGuru = verifikasiPinGuru;

