function eksekusiLogoutSiswa() {
  try { playSound('click'); } catch (e) {}
  const profile = getActiveStudentProfile();
  const elWelcomeNama = document.getElementById('welcome-siswa-nama');
  const nama = profile ? profile.nama : (elWelcomeNama ? elWelcomeNama.innerText.trim() : 'Siswa');

  // Simpan pekerjaan Word & Excel siswa yang sedang keluar terlebih dahulu
  try { if (typeof simpanWordDraftSiswa === 'function') simpanWordDraftSiswa(); } catch (e) {}
  try { if (typeof simpanExcelDraftSiswa === 'function') simpanExcelDraftSiswa(); } catch (e) {}

  // 1. Bersihkan data sesi siswa di seluruh lapisan penyimpanan secara tuntas
  clearActiveStudentSession();
  if (typeof state !== 'undefined') {
    state.userPoints = 0;
  }

  // 2. Tutup semua modal siswa terkait
  try { tutupModalKonfirmasiLogoutSiswa(); } catch (e) {}
  const modalProfil = document.getElementById('modal-profil-siswa');
  if (modalProfil) {
    modalProfil.classList.add('hidden');
    modalProfil.style.setProperty('display', 'none', 'important');
    modalProfil.style.setProperty('visibility', 'hidden', 'important');
    modalProfil.style.setProperty('pointer-events', 'none', 'important');
  }

  // 3. Hapus style awal siswa agar peramban tidak lagi memaksa dock siswa
  try {
    const earlyStyle = document.getElementById('style-early-student-session');
    if (earlyStyle) earlyStyle.remove();
  } catch (e) {}

  // 4. Reset poin di layar
  const p1 = document.getElementById('user-points');
  const p2 = document.getElementById('user-points-sem1');
  const pWelcome = document.getElementById('welcome-siswa-bintang');
  if (p1) p1.innerText = '0';
  if (p2) p2.innerText = '0';
  if (pWelcome) pWelcome.innerText = '0';

  // 5. Bersihkan kanvas Paint & kuis agar karya/sertifikat siswa tidak tertinggal untuk siswa berikutnya
  try { if (typeof resetPaintCanvasUntukSiswa === 'function') resetPaintCanvasUntukSiswa(); } catch (e) {}
  try { if (typeof restartQuiz === 'function') restartQuiz(); } catch (e) {}

  // 6. Muat ulang tampilan profil siswa ke status Tamu / Belum Masuk
  try { muatProfilSiswa(); } catch (e) {}
  try { setHeaderNavMode('utama'); } catch (e) {}

  // 7. Perbarui elemen bar sambutan siswa secara eksplisit seketika
  const elAvatar = document.getElementById('welcome-siswa-avatar');
  const elNama = document.getElementById('welcome-siswa-nama');
  const elKelas = document.getElementById('welcome-siswa-kelas');
  const elSub = document.getElementById('welcome-siswa-sub-text');
  const elPing = document.getElementById('welcome-siswa-ping');
  const btnLogin = document.getElementById('btn-welcome-login');
  const btnLogout = document.getElementById('btn-welcome-logout');
  const btnRapor = document.getElementById('btn-welcome-rapor');
  const btnGanti = document.getElementById('btn-welcome-ganti');
  const btnSemToggle = document.getElementById('btn-toggle-sem-siswa');
  const bintangWrap = document.getElementById('welcome-siswa-bintang-wrap');

  if (elAvatar) {
    elAvatar.innerText = '👤';
    elAvatar.className = 'w-11 h-11 rounded-2xl bg-slate-200 text-slate-500 flex items-center justify-center font-black text-lg shadow-inner flex-shrink-0';
  }
  if (elNama) elNama.innerText = 'Belum Ada Siswa Masuk';
  if (elKelas) {
    elKelas.innerText = 'Akun Belum Aktif';
    elKelas.className = 'px-2.5 py-0.5 rounded-full text-[11px] font-bold bg-slate-100 text-slate-500 border border-slate-300';
  }
  if (elSub) elSub.innerText = 'Lab Komputer • Belum Masuk Akun';
  if (elPing) elPing.classList.add('hidden');
  if (bintangWrap) bintangWrap.classList.add('hidden');

  if (btnLogin) { 
    btnLogin.classList.remove('hidden'); 
    btnLogin.style.removeProperty('display'); 
    btnLogin.style.setProperty('display', 'inline-flex', 'important'); 
  }
  if (btnLogout) { 
    btnLogout.classList.add('hidden'); 
    btnLogout.style.setProperty('display', 'none', 'important'); 
  }
  if (btnRapor) { 
    btnRapor.classList.add('hidden'); 
    btnRapor.style.setProperty('display', 'none', 'important'); 
  }
  if (btnGanti) { 
    btnGanti.classList.add('hidden'); 
    btnGanti.style.setProperty('display', 'none', 'important'); 
  }
  if (btnSemToggle) { 
    btnSemToggle.classList.add('hidden'); 
    btnSemToggle.style.setProperty('display', 'none', 'important'); 
  }

  const heroGuest = document.getElementById('hero-guest-btn');
  const heroSem = document.getElementById('hero-sem-buttons');
  if (heroGuest) heroGuest.classList.remove('hidden');
  if (heroSem) heroSem.classList.add('hidden');

  const cardsSiswa = document.getElementById('beranda-fitur-cards-siswa');
  if (cardsSiswa) cardsSiswa.classList.add('hidden');

  const navUtama = document.getElementById('navbar-tampilan-utama');
  if (navUtama) { 
    navUtama.classList.remove('hidden'); 
    navUtama.style.removeProperty('display');
    navUtama.style.setProperty('display', 'flex', 'important'); 
  }
  const navSem1 = document.getElementById('navbar-tampilan-sem1');
  if (navSem1) { 
    navSem1.classList.add('hidden'); 
    navSem1.style.setProperty('display', 'none', 'important'); 
  }
  const navKelas5 = document.getElementById('navbar-tampilan-kelas5');
  if (navKelas5) { 
    navKelas5.classList.add('hidden'); 
    navKelas5.style.setProperty('display', 'none', 'important'); 
  }

  try { if (typeof renderGaleriPosterWord === 'function') renderGaleriPosterWord(); } catch (e) {}
  try { if (typeof renderDrive7KebiasaanGrid === 'function') renderDrive7KebiasaanGrid(); } catch (e) {}
  try { switchTab('beranda'); } catch (e) {}
  try { window.scrollTo({ top: 0, left: 0, behavior: 'instant' }); } catch (e) {}

  showToast(`Akun ${nama} berhasil keluar! Sesi telah diamankan 🔒`, 'info');
}
window.eksekusiLogoutSiswa = eksekusiLogoutSiswa;

function renderOpsiPilihSiswa() {
  const dropdown = document.getElementById('pilih-cepat-siswa-dropdown');
  if (!dropdown) return;

  const db = getStudentDatabase();
  const currentProfile = getActiveStudentProfile() || {};

  dropdown.innerHTML = '<option value="">-- Pilih Nama Siswa dari Database Kelas --</option>';

  const classes = ['4A', '4B', '4C', '4D', '4E', '5A', '5B', '5C', '5D', '5E', '6A', '6B', '6C', '6D', '6E'];
  classes.forEach(cls => {
    const group = document.createElement('optgroup');
    group.label = `Kelas ${cls}`;
    const studentsInClass = db.filter(s => s.kelas === cls);
    const sortedStudentsInClass = urutkanSiswaSesuaiNomorAbsen(studentsInClass);

    sortedStudentsInClass.forEach(s => {
      const opt = document.createElement('option');
      opt.value = s.id;
      opt.innerText = `NIS: ${s.nis || '-'} • No.${s.absen || '-'} - ${s.nama}`;
      if (s.id === currentProfile.id || (currentProfile.nis && s.nis === currentProfile.nis)) {
        opt.selected = true;
      }
      group.appendChild(opt);
    });

    dropdown.appendChild(group);
  });
}

function pilihSiswaDariDropdown(studentId) {
  if (!studentId) return;
  playSound('success');
  const db = getStudentDatabase();
  const student = db.find(s => s.id === studentId);
  if (!student) return;

  const profile = {
    id: student.id,
    nis: student.nis || '4101',
    nama: student.nama,
    kelas: student.kelas,
    absen: student.absen
  };
  const isKelas5 = String(profile.kelas || '').includes('5');
  const targetTab = isKelas5 ? 'petualangan5' : ((typeof state !== 'undefined' && state.currentTab && state.currentTab !== 'petualangan5') ? state.currentTab : 'beranda');
  saveActiveStudentSession(profile, targetTab);

  // Perbarui poin aktif sesuai poin tersimpan siswa
  state.userPoints = student.poinBintang || 0;
  const p1 = document.getElementById('user-points');
  const p2 = document.getElementById('user-points-sem1');
  if (p1) p1.innerText = state.userPoints;
  if (p2) p2.innerText = state.userPoints;

  muatProfilSiswa();
  setHeaderNavMode(isKelas5 ? 'kelas5' : 'sem1');
  renderGaleriPosterWord();
  tutupModalProfilSiswa();
  switchTab(targetTab);
  showToast(`Berhasil masuk sebagai ${student.nama} (${student.kelas} • NIS: ${student.nis})! 🎉`, 'success');
}

function simpanProfilSiswa() {
  const inputNama = document.getElementById('input-profil-nama');
  const inputNis = document.getElementById('input-profil-nis');
  const inputKelas = document.getElementById('input-profil-kelas');
  const inputAbsen = document.getElementById('input-profil-absen');

  const nama = inputNama ? inputNama.value.trim() : '';
  const kelas = inputKelas ? inputKelas.value : '4A';
  let absen = inputAbsen ? inputAbsen.value.trim() : '01';
  if (absen.length === 1) absen = '0' + absen;
  let nis = inputNis ? inputNis.value.trim() : '';
  if (!nis) {
    const clsMap = { '4A': '41', '4B': '42', '4C': '43', '4D': '44', '4E': '45', '5A': '51', '5B': '52', '5C': '53', '5D': '54', '5E': '55', '6A': '61', '6B': '62', '6C': '63', '6D': '64', '6E': '65' };
    const clsCode = clsMap[kelas] || '41';
    nis = `${clsCode}${absen}`;
  }

  if (!nama) {
    showToast('Silakan masukkan nama lengkap siswa!', 'error');
    return;
  }

  const id = `STD-${kelas}-${absen}`;
  const profile = { id, nis, nama, kelas, absen };
  const isKelas5 = String(kelas || '').includes('5');
  const targetTabSimpan = isKelas5 ? 'petualangan5' : ((typeof state !== 'undefined' && state.currentTab && state.currentTab !== 'petualangan5') ? state.currentTab : 'beranda');
  saveActiveStudentSession(profile, targetTabSimpan);

  // Pastikan siswa ini ada di database guru
  const db = getStudentDatabase();
  const existIdx = db.findIndex(s => s.id === id || s.nis === nis || (s.nama.toLowerCase() === nama.toLowerCase() && s.kelas === kelas));
  if (existIdx >= 0) {
    db[existIdx].nama = nama;
    db[existIdx].nis = nis;
    db[existIdx].kelas = kelas;
    db[existIdx].absen = absen;
    db[existIdx].poinBintang = Math.max(db[existIdx].poinBintang, state.userPoints);
    db[existIdx].terakhirAktif = 'Baru saja';
  } else {
    db.push({
      id: id,
      nis: nis,
      nama: nama,
      kelas: kelas,
      absen: absen,
      kuisSem1: 0,
      kuisSem2: 0,
      tpSelesai: ['TP 1.1'],
      posterWord: 0,
      excelTabel: 0,
      poinBintang: state.userPoints || 0,
      statusKkm: 'Tuntas',
      terakhirAktif: 'Baru saja',
      catatanGuru: 'Siswa baru terdaftar.'
    });
  }
  saveStudentDatabase(db);

  muatProfilSiswa();
  setHeaderNavMode(isKelas5 ? 'kelas5' : 'sem1');
  renderGaleriPosterWord();
  tutupModalProfilSiswa();
  switchTab(targetTabSimpan);
  showToast(`Halo ${nama}! Profilmu (${kelas} • NIS: ${nis}) berhasil disimpan & aktif 🎉`, 'success');
}

// ==========================================
// ISOLASI LEMBAR KERJA MS WORD, EXCEL & PAINT PER AKUN SISWA (NIS)
// ==========================================
function simpanWordDraftSiswa() {
  try {
    const key = getActiveStudentStorageKey('educode_word_active_draft');
    const draft = {
      title: currentWordDocTitle || 'Poster_7_Kebiasaan',
      elements: JSON.parse(JSON.stringify(wordElements || [])),
      pageBgColor: wordPageBgColor || '#ffffff',
      pageBorderStyle: wordPageBorderStyle || 'solid',
      timestamp: Date.now()
    };
    localStorage.setItem(key, JSON.stringify(draft));
  } catch (e) {}
}
window.simpanWordDraftSiswa = simpanWordDraftSiswa;

function muatWordDraftSiswa() {
  try {
    const key = getActiveStudentStorageKey('educode_word_active_draft');
    const raw = localStorage.getItem(key);
    if (raw) {
      const draft = JSON.parse(raw);
      if (draft && Array.isArray(draft.elements) && draft.elements.length > 0) {
        wordElements = draft.elements;
        currentWordDocTitle = draft.title || 'Poster_7_Kebiasaan';
        wordPageBgColor = draft.pageBgColor || '#ffffff';
        wordPageBorderStyle = draft.pageBorderStyle || 'solid';
        const docNameInput = document.getElementById('word-doc-name-input');
        if (docNameInput) docNameInput.value = currentWordDocTitle;
        const titleDisplay = document.getElementById('word-doc-title-display');
        if (titleDisplay) titleDisplay.innerText = `${currentWordDocTitle}.docx - Word`;
        renderWordElements();
        return;
      }
    }
  } catch (e) {}

  // Jika siswa belum punya draft tersimpan, mulai lembar poster baru yang bersih
  loadPresetPosterLingkungan('indonesia_hebat');
  const profile = getActiveStudentProfile();
  if (profile) {
    const formatBaku = `${profile.kelas}_${(profile.nama || 'Siswa').split(' ')[0]}_Poster 7 Kebiasaan`;
    currentWordDocTitle = formatBaku;
    const docNameInput = document.getElementById('word-doc-name-input');
    if (docNameInput) docNameInput.value = formatBaku;
    const titleDisplay = document.getElementById('word-doc-title-display');
    if (titleDisplay) titleDisplay.innerText = `${formatBaku}.docx - Word`;
  }
}
window.muatWordDraftSiswa = muatWordDraftSiswa;

function simpanExcelDraftSiswa() {
  try {
    if (typeof excelState === 'undefined' || !excelState.cells) return;
    const key = getActiveStudentStorageKey('educode_excel_active_cells');
    const draft = {
      template: excelState.activeTemplate || 'checklist_karakter',
      cells: JSON.parse(JSON.stringify(excelState.cells)),
      formats: JSON.parse(JSON.stringify(excelState.formats || {})),
      timestamp: Date.now()
    };
    localStorage.setItem(key, JSON.stringify(draft));
  } catch (e) {}
}
window.simpanExcelDraftSiswa = simpanExcelDraftSiswa;

function muatExcelDraftSiswa() {
  try {
    if (typeof excelState === 'undefined') return;
    const key = getActiveStudentStorageKey('educode_excel_active_cells');
    const raw = localStorage.getItem(key);
    if (raw) {
      const draft = JSON.parse(raw);
      if (draft && draft.cells && Object.keys(draft.cells).length > 0) {
        excelState.activeTemplate = draft.template || 'checklist_karakter';
        excelState.cells = draft.cells;
        if (draft.formats) excelState.formats = draft.formats;
        renderExcelGrid();
        renderExcelMiniChart();
        updateExcelStats();
        return;
      }
    }
  } catch (e) {}

  // Template default baru jika siswa belum pernah mengisi
  if (typeof muatTemplateExcel === 'function') {
    muatTemplateExcel('checklist_karakter', false);
  }
}
window.muatExcelDraftSiswa = muatExcelDraftSiswa;

function resetPaintCanvasUntukSiswa() {
  try {
    if (typeof paintApp !== 'undefined' && paintApp.canvas && paintApp.ctx) {
      paintApp.ctx.fillStyle = '#ffffff';
      paintApp.ctx.fillRect(0, 0, paintApp.canvas.width, paintApp.canvas.height);
      paintApp.history = [];
      paintApp.redoList = [];
      paintApp.activeObject = null;
      if (typeof updatePaintCommitButton === 'function') updatePaintCommitButton();
      if (typeof savePaintState === 'function') savePaintState();
    }
  } catch (e) {}
}
window.resetPaintCanvasUntukSiswa = resetPaintCanvasUntukSiswa;

function muatProfilSiswa() {
  let profile = null;
  let student = null;
  try {
    profile = (typeof getActiveStudentProfile === 'function') ? getActiveStudentProfile() : null;
  } catch (eP) {}

  if (!profile) {
    try {
      const raw = localStorage.getItem(ACTIVE_STUDENT_KEY);
      if (raw && raw !== 'LOGGED_OUT' && raw !== 'null' && raw !== 'undefined' && raw.indexOf('{') !== -1) {
        profile = JSON.parse(raw);
        window.__ACTIVE_STUDENT_PROFILE__ = profile;
        window.__ACTIVE_STUDENT_RESTORED__ = profile;
      }
    } catch (eRaw) {}
  }

  const firstName = (profile && profile.nama) ? profile.nama.split(' ')[0] : 'Siswa';
  const labelUtama = document.getElementById('label-profil-siswa');
  if (labelUtama) {
    labelUtama.innerText = profile ? `${firstName} (${profile.kelas})` : 'Belum Masuk';
  }
  document.querySelectorAll('.label-profil-siswa-sync').forEach(el => {
    el.innerText = profile ? `${firstName} (${profile.kelas})` : 'Belum Masuk';
  });

  // Perbarui Bar Sambutan Siswa di Beranda Seketika & Prioritas Utama
  const welcomeAvatar = document.getElementById('welcome-siswa-avatar');
  const welcomeNama = document.getElementById('welcome-siswa-nama');
  const welcomeKelas = document.getElementById('welcome-siswa-kelas');
  const welcomeBintang = document.getElementById('welcome-siswa-bintang');
  const welcomeSubText = document.getElementById('welcome-siswa-sub-text');
  const welcomePing = document.getElementById('welcome-siswa-ping');
  const btnRapor = document.getElementById('btn-welcome-rapor');
  const btnGanti = document.getElementById('btn-welcome-ganti');
  const btnLogout = document.getElementById('btn-welcome-logout');
  const btnLogin = document.getElementById('btn-welcome-login');
  const bintangWrap = document.getElementById('welcome-siswa-bintang-wrap');

  const heroSemBtns = document.getElementById('hero-sem-buttons');
  const heroGuestBtn = document.getElementById('hero-guest-btn');
  const btnSemToggle = document.getElementById('btn-toggle-sem-siswa');

  if (!profile || (!profile.nama && !profile.nis && !profile.id)) {
    // Mode Guest / Signed Out
    if (heroSemBtns) heroSemBtns.classList.add('hidden');
    if (heroGuestBtn) heroGuestBtn.classList.remove('hidden');
    if (welcomeAvatar) {
      welcomeAvatar.innerText = '👤';
      welcomeAvatar.className = 'w-11 h-11 rounded-2xl bg-slate-200 text-slate-500 flex items-center justify-center font-black text-lg shadow-inner flex-shrink-0';
    }
    if (welcomeSubText) welcomeSubText.innerText = 'Lab Komputer • Belum Masuk Akun';
    if (welcomePing) welcomePing.classList.add('hidden');
    if (welcomeNama) welcomeNama.innerText = 'Belum Ada Siswa Masuk';
    if (welcomeKelas) {
      welcomeKelas.innerText = 'Akun Belum Aktif';
      welcomeKelas.className = 'px-2.5 py-0.5 rounded-full text-[11px] font-bold bg-slate-100 text-slate-500 border border-slate-300';
    }
    if (welcomeBintang) welcomeBintang.innerText = '0';
    if (bintangWrap) bintangWrap.classList.add('hidden');
    if (btnSemToggle) {
      btnSemToggle.classList.add('hidden');
      btnSemToggle.style.removeProperty('display');
      btnSemToggle.style.setProperty('display', 'none', 'important');
    }
    if (btnRapor) { 
      btnRapor.classList.add('hidden'); 
      btnRapor.style.removeProperty('display');
      btnRapor.style.setProperty('display', 'none', 'important'); 
    }
    if (btnGanti) { 
      btnGanti.classList.add('hidden'); 
      btnGanti.style.removeProperty('display');
      btnGanti.style.setProperty('display', 'none', 'important'); 
    }
    if (btnLogout) { 
      btnLogout.classList.add('hidden'); 
      btnLogout.style.removeProperty('display');
      btnLogout.style.setProperty('display', 'none', 'important'); 
    }
    if (btnLogin) { 
      btnLogin.classList.remove('hidden'); 
      btnLogin.style.removeProperty('display');
      btnLogin.style.setProperty('display', 'inline-flex', 'important'); 
    }

    const cardsSiswa = document.getElementById('beranda-fitur-cards-siswa');
    if (cardsSiswa) cardsSiswa.classList.add('hidden');

    state.userPoints = 0;
    const p1 = document.getElementById('user-points');
    const p2 = document.getElementById('user-points-sem1');
    if (p1) p1.innerText = 0;
    if (p2) p2.innerText = 0;
    const isTeacher = (typeof isTeacherSessionActive === 'function' && isTeacherSessionActive()) || 
                      (typeof state !== 'undefined' && state.isGuruLoggedIn) ||
                      (window.__TEACHER_SESSION_ACTIVE__ === true);
    if (!isTeacher) {
      setHeaderNavMode('utama');
    } else {
      setHeaderNavMode('guru');
    }
  } else {
    // Mode Siswa Aktif (Tampilkan Profil, Tombol Keluar & Dock Navigasi Siswa)
    try { injectOrUpdateStudentStyle(profile); } catch (eSt) {}
    if (heroSemBtns) heroSemBtns.classList.remove('hidden');
    if (heroGuestBtn) heroGuestBtn.classList.add('hidden');
    const cardsSiswa = document.getElementById('beranda-fitur-cards-siswa');
    if (cardsSiswa) cardsSiswa.classList.remove('hidden');
    const isKelas5 = String(profile.kelas || '').includes('5');
    setHeaderNavMode(isKelas5 ? 'kelas5' : 'sem1');
    if (welcomeAvatar) {
      welcomeAvatar.innerText = profile.nama ? profile.nama.charAt(0).toUpperCase() : 'S';
      welcomeAvatar.className = 'w-11 h-11 rounded-2xl bg-gradient-to-tr from-emerald-500 to-teal-400 text-white flex items-center justify-center font-black text-base shadow-md flex-shrink-0';
    }
    if (welcomeSubText) welcomeSubText.innerText = 'Selamat Belajar di Tzu Chi';
    if (welcomePing) welcomePing.classList.remove('hidden');
    if (welcomeNama) welcomeNama.innerText = profile.nama || 'Siswa';
    if (welcomeKelas) {
      welcomeKelas.innerText = `Kelas ${profile.kelas || (isKelas5 ? '5D' : '4A')} • Absen ${profile.absen || '-'}`;
      welcomeKelas.className = 'px-2.5 py-0.5 rounded-full text-[11px] font-bold bg-emerald-50 text-emerald-700 border border-emerald-300';
    }

    // Tombol Keluar & Masuk - Eksplisit & Prioritas Tertinggi
    if (btnLogout) { 
      btnLogout.classList.remove('hidden'); 
      btnLogout.style.removeProperty('display');
      btnLogout.style.setProperty('display', 'inline-flex', 'important'); 
    }
    if (btnLogin) { 
      btnLogin.classList.add('hidden'); 
      btnLogin.style.removeProperty('display');
      btnLogin.style.setProperty('display', 'none', 'important'); 
    }
    if (btnRapor) { 
      btnRapor.classList.remove('hidden'); 
      btnRapor.style.removeProperty('display');
      btnRapor.style.setProperty('display', 'inline-flex', 'important'); 
    }
    if (btnGanti) { 
      btnGanti.classList.remove('hidden'); 
      btnGanti.style.removeProperty('display');
      btnGanti.style.setProperty('display', 'inline-flex', 'important'); 
    }

    let activePoints = (typeof state !== 'undefined' && state.userPoints) ? state.userPoints : 0;
    try {
      const db = getStudentDatabase();
      student = (Array.isArray(db)) ? db.find(s => s.id === profile.id || (String(s.nama || '').toLowerCase() === String(profile.nama || '').toLowerCase() && s.kelas === profile.kelas)) : null;
      if (student && student.poinBintang !== undefined) {
        activePoints = student.poinBintang;
      }
    } catch (eDb) {}

    if (typeof state !== 'undefined') state.userPoints = activePoints;
    if (welcomeBintang) welcomeBintang.innerText = activePoints;
    const p1 = document.getElementById('user-points');
    const p2 = document.getElementById('user-points-sem1');
    if (p1) p1.innerText = activePoints;
    if (p2) p2.innerText = activePoints;
    if (bintangWrap) bintangWrap.classList.remove('hidden');

    if (btnSemToggle) {
      if (isSemester2Unlocked()) {
        btnSemToggle.classList.remove('hidden');
        btnSemToggle.style.removeProperty('display');
        btnSemToggle.style.setProperty('display', 'inline-flex', 'important');
      } else {
        btnSemToggle.classList.add('hidden');
        btnSemToggle.style.removeProperty('display');
        btnSemToggle.style.setProperty('display', 'none', 'important');
      }
    }

    updateNavSemesterVisibility();
    updateLabelSemesterSiswa();
  }

  // Perbarui Badge Profil Siswa di Title Bar Lab MS Word
  try {
    const wordAvatar = document.getElementById('word-account-avatar');
    const wordName = document.getElementById('word-account-name');
    if (wordAvatar && wordName) {
      if (profile && profile.nama) {
        const parts = profile.nama.trim().split(/\s+/);
        const initials = parts.length > 1 ? (parts[0][0] + parts[1][0]).toUpperCase() : parts[0].substring(0, 2).toUpperCase();
        wordAvatar.innerText = initials;
        wordName.innerText = profile.nama;
      } else {
        wordAvatar.innerText = '👤';
        wordName.innerText = 'Tamu (Belum Masuk)';
      }
    }
  } catch (eWordBadge) {}

  // Muat draft dokumen Word & tabel Excel mandiri milik siswa yang sedang aktif secara aman
  try { muatWordDraftSiswa(); } catch (eDraftW) {}
  try { muatExcelDraftSiswa(); } catch (eDraftE) {}

  // Perbarui nama di Sertifikat Kuis sesuai siswa yang sedang login
  try {
    const certStudentName = document.getElementById('cert-student-name');
    if (certStudentName) {
      if (profile && profile.nama) {
        certStudentName.value = `${profile.nama} (${profile.kelas || 'Kelas 4'})`;
      } else {
        certStudentName.value = 'Siswa Berbakat Kelas 4';
      }
    }
  } catch (eCert) {}

  // Segarkan tampilan grid Drive 7 Kebiasaan & Galeri Poster khusus milik akun siswa yang aktif
  try {
    if (typeof renderDrive7KebiasaanGrid === 'function') {
      renderDrive7KebiasaanGrid();
    }
  } catch (eDrive) {}
  try {
    if (typeof renderGaleriPosterWord === 'function') {
      renderGaleriPosterWord();
    }
  } catch (ePoster) {}

  // Sinkronkan portofolio karya poster & Drive siswa dari Cloud Firebase (Hanya jika Cloud Aktif)
  try {
    if (profile && isFirebaseConnected && typeof sinkronkanKaryaSiswaDariCloud === 'function') {
      sinkronkanKaryaSiswaDariCloud(profile);
    }
  } catch (eCloud) {}

  // Perbarui tombol sertifikat di Kuis & Banner Modul
  try {
    const btnLihatSertifikatTop = document.getElementById('btn-lihat-sertifikat-top');
    const btnTextSertifikatModul = document.getElementById('btn-text-sertifikat-modul');
    const hasFinishedKuis = student && ((state.currentSemester === 2 ? student.kuisSem2 : student.kuisSem1) > 0);

    if (btnLihatSertifikatTop) {
      if (hasFinishedKuis) {
        btnLihatSertifikatTop.classList.remove('hidden');
      } else {
        btnLihatSertifikatTop.classList.add('hidden');
      }
    }

    if (btnTextSertifikatModul) {
      if (hasFinishedKuis) {
        btnTextSertifikatModul.innerText = 'Lihat Sertifikat Digital Saya 🏆';
      } else {
        btnTextSertifikatModul.innerText = 'Ikuti Kuis & Ambil Sertifikat 🏆';
      }
    }
  } catch (eKuisCert) {}
}
window.muatProfilSiswa = muatProfilSiswa;

// Pengawas Otomatis Tab Beranda: Memastikan bar sambutan siswa 100% selalu menampilkan nama & tombol Keluar saat tab Beranda terbuka
(function initBerandaTabObserver() {
  function periksaDanSinkronkanBeranda() {
    const tabBeranda = document.getElementById('tab-beranda');
    if (!tabBeranda) return;
    const isVisible = !tabBeranda.classList.contains('hidden') && tabBeranda.style.display !== 'none';
    if (isVisible) {
      let profile = null;
      try {
        profile = (typeof getActiveStudentProfile === 'function') ? getActiveStudentProfile() : null;
      } catch (eProf) {}
      if (!profile) {
        try {
          const raw = localStorage.getItem('educode_active_student_v1');
          if (raw && raw !== 'LOGGED_OUT' && raw.indexOf('{') !== -1) {
            profile = JSON.parse(raw);
          }
        } catch (eR) {}
      }
      if (profile && (profile.nama || profile.nis || profile.id)) {
        if (typeof muatProfilSiswa === 'function') {
          muatProfilSiswa();
        }
      }
    }
  }

  if (typeof MutationObserver !== 'undefined') {
    const observer = new MutationObserver(function() {
      periksaDanSinkronkanBeranda();
    });
    const attachObserver = function() {
      const tabBeranda = document.getElementById('tab-beranda');
      if (tabBeranda) {
        observer.observe(tabBeranda, { attributes: true, attributeFilter: ['class', 'style'] });
      }
    };
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', attachObserver);
    } else {
      attachObserver();
    }
  }
})();

function syncPoinSiswaKeDb(poin) {
  try {
    const profile = getActiveStudentProfile();
    if (!profile) return;
    const db = getStudentDatabase();
    const student = db.find(s => s.id === profile.id || (s.nama.toLowerCase() === profile.nama.toLowerCase() && s.kelas === profile.kelas));
    if (student) {
      student.poinBintang = poin;
      student.terakhirAktif = 'Baru saja';
      saveStudentDatabase(db);
    }
  } catch (e) {}
}

function catatHasilKuisSiswa(semNumber, score) {
  try {
    const profile = getActiveStudentProfile();
    if (!profile) {
      showToast('⚠️ Silakan masuk/pilih akun siswa terlebih dahulu agar skor kuismu tercatat!', 'warning');
      bukaPilihSiswaCepat();
      return;
    }
    const db = getStudentDatabase();
    let student = db.find(s => (profile.nis && s.nis === profile.nis) || s.id === profile.id || (s.nama.toLowerCase() === profile.nama.toLowerCase() && s.kelas === profile.kelas));
    if (!student) {
      student = {
        id: profile.id,
        nis: profile.nis || '4101',
        nama: profile.nama,
        kelas: profile.kelas,
        absen: profile.absen,
        kuisSem1: 0,
        kuisSem2: 0,
        tpSelesai: ['TP 1.1', 'TP 2.1'],
        posterWord: 0,
        excelTabel: 0,
        poinBintang: state.userPoints,
        statusKkm: 'Tuntas',
        terakhirAktif: 'Baru saja',
        catatanGuru: ''
      };
      db.push(student);
    }

    if (semNumber === 1) {
      student.kuisSem1 = Math.max(student.kuisSem1 || 0, score);
    } else {
      student.kuisSem2 = Math.max(student.kuisSem2 || 0, score);
    }

    const avg = ((student.kuisSem1 || 0) + (student.kuisSem2 || 0)) / ((student.kuisSem1 ? 1 : 0) + (student.kuisSem2 ? 1 : 0) || 1);
    student.statusKkm = avg >= 80 ? 'Tuntas' : 'Remedial';
    student.terakhirAktif = 'Baru saja';
    saveStudentDatabase(db);

    // Simpan riwayat kuis mandiri ke LocalStorage per NIS siswa
    try {
      const quizKey = getActiveStudentStorageKey('educode_quiz_record_sem' + semNumber);
      localStorage.setItem(quizKey, JSON.stringify({
        semester: semNumber,
        skor: score,
        nis: student.nis || profile.nis || '',
        nama: student.nama,
        kelas: student.kelas,
        waktu: new Date().toLocaleString('id-ID')
      }));
    } catch (eStorage) {}

    // Kirim sinkronisasi otomatis ke Google Sheets jika webhook aktif
    kirimKeWebhookSheets({
      event: 'kuis_selesai',
      nis: student.nis || profile.nis || '',
      nama: student.nama,
      kelas: student.kelas,
      absen: student.absen,
      semester: semNumber,
      skor: score,
      statusKkm: student.statusKkm,
      poinBintang: state.userPoints,
      timestamp: new Date().toISOString()
    });
  } catch (e) {
    console.warn('Gagal mencatat kuis siswa ke database:', e);
  }
}

// ==========================================================================
// SISTEM PENILAIAN OTOMATIS BERBASIS RUBRIK (POSTER WORD & TABEL EXCEL)
// ==========================================================================

// 1. Rubrik Penilaian Otomatis Poster Word (0-100)
function hitungRubrikOtomatisPosterWord(elements = [], title = '', bgColor = '#ffffff', borderStyle = 'solid') {
  const currentEls = Array.isArray(elements) && elements.length > 0 ? elements : (typeof wordElements !== 'undefined' ? wordElements : []);
  const curTitle = title || (typeof currentWordDocTitle !== 'undefined' ? currentWordDocTitle : 'Poster Digital');
  const curBg = bgColor || (typeof wordPageBgColor !== 'undefined' ? wordPageBgColor : '#ffffff');
  const curBorder = borderStyle || (typeof wordPageBorderStyle !== 'undefined' ? wordPageBorderStyle : 'solid');

  // Aspek 1: Kelengkapan Elemen Konten (Maks 25 Poin)
  let aspek1 = 0;
  const hasJudul = currentEls.some(e => e.type === 'teks' && (e.subtype === 'judul' || (e.fontSizePx && e.fontSizePx >= 20) || e.isBold));
  const hasSlogan = currentEls.some(e => e.type === 'teks' && (e.subtype === 'slogan' || (e.text && e.text.length > 8 && e.subtype !== 'judul')));
  const hasGambar = currentEls.some(e => e.type === 'gambar' || e.type === 'shape' || e.type === 'gambar_luar');

  if (hasJudul) aspek1 += 10;
  if (hasSlogan) aspek1 += 8;
  if (hasGambar) aspek1 += 7;
  if (aspek1 === 0 && currentEls.length > 0) aspek1 = 15;

  // Aspek 2: Kesesuaian Tema Budi Pekerti (Maks 25 Poin)
  let aspek2 = 12;
  const combinedText = (curTitle + ' ' + currentEls.filter(e => e.type === 'teks').map(e => e.text || '').join(' ')).toLowerCase();
  const keywords = ['hemat', 'energi', 'listrik', 'air', 'bumi', 'lestari', 'tzu chi', 'cinta', 'kasih', 'lingkungan', 'daur ulang', 'karakter', 'kebiasaan', 'hebat', 'hijau', 'pohon', 'sampah', 'disiplin', 'sayang', 'belajar', 'bersih'];
  let matchCount = 0;
  keywords.forEach(kw => {
    if (combinedText.includes(kw)) matchCount++;
  });
  if (matchCount >= 3) aspek2 = 25;
  else if (matchCount === 2) aspek2 = 22;
  else if (matchCount === 1) aspek2 = 18;
  else aspek2 = 14;

  // Aspek 3: Kerapian Tata Letak & Variasi (Maks 25 Poin)
  let aspek3 = 15;
  if (currentEls.length >= 2) {
    const yPos = currentEls.map(e => e.y || 0);
    const spreadY = Math.max(...yPos) - Math.min(...yPos);
    if (spreadY > 200) aspek3 = 25;
    else if (spreadY > 100) aspek3 = 21;
    else aspek3 = 17;
  }

  // Aspek 4: Harmonisasi Warna & Bingkai (Maks 25 Poin)
  let aspek4 = 15;
  if (curBorder && curBorder !== 'none') aspek4 += 5;
  if (curBg && curBg !== '#ffffff') aspek4 += 5;
  if (currentEls.length >= 4) aspek4 = Math.min(25, aspek4 + 3);

  const totalSkor = Math.min(100, Math.max(50, aspek1 + aspek2 + aspek3 + aspek4));
  return {
    totalSkor,
    aspek1,
    aspek2,
    aspek3,
    aspek4,
    grade: totalSkor >= 90 ? 'Sangat Baik (A)' : totalSkor >= 75 ? 'Baik (B)' : 'Cukup (C)'
  };
}

// 2. Rubrik Penilaian Otomatis Tabel Excel (0-100)
function hitungRubrikOtomatisExcel() {
  const tpl = (typeof excelState !== 'undefined' && EXCEL_TEMPLATES && EXCEL_TEMPLATES[excelState.activeTemplate]) || {};
  const cells = (typeof excelState !== 'undefined' && excelState.cells) ? excelState.cells : {};
  const rowCount = (typeof excelState !== 'undefined' && excelState.rowCount) ? excelState.rowCount : 7;
  const formats = (typeof excelState !== 'undefined' && excelState.formats) || tpl.formats || {};

  // Aspek 1: Struktur Kolom & Header Tabel (Maks 25 Poin)
  let aspek1 = 16;
  if (rowCount >= 5) aspek1 = 25;
  else if (rowCount >= 3) aspek1 = 21;

  // Aspek 2: Penggunaan Formula Rumus (Maks 25 Poin)
  let aspek2 = 15;
  let formulaCount = 0;
  Object.values(cells).forEach(val => {
    if (typeof val === 'string' && val.trim().startsWith('=')) {
      formulaCount++;
    }
  });
  if (formulaCount >= 3) aspek2 = 25;
  else if (formulaCount >= 1) aspek2 = 22;
  else aspek2 = 18;

  // Aspek 3: Format Sel & Garis Border (Maks 25 Poin)
  let aspek3 = 18;
  const hasFormats = Object.keys(formats).length > 0;
  if (hasFormats) {
    const hasBold = Object.values(formats).some(f => f.bold);
    const hasBg = Object.values(formats).some(f => f.bg);
    if (hasBold && hasBg) aspek3 = 25;
    else if (hasBold || hasBg) aspek3 = 22;
  }

  // Aspek 4: Kerapian Tipe Data & Angka (Maks 25 Poin)
  let aspek4 = 18;
  const hasNumFormat = Object.values(formats).some(f => f.numFormat || f.align === 'right' || f.align === 'center');
  if (hasNumFormat) aspek4 = 25;
  else aspek4 = 20;

  const totalSkor = Math.min(100, Math.max(60, aspek1 + aspek2 + aspek3 + aspek4));
  return {
    totalSkor,
    aspek1,
    aspek2,
    aspek3,
    aspek4,
    grade: totalSkor >= 90 ? 'Sangat Baik (A)' : totalSkor >= 75 ? 'Baik (B)' : 'Cukup (C)'
  };
}

