// KONTROL DOCK GURU & FILTER KELAS (DARNINGSIH, S.T. | KELAS 4 | KELAS 5 | KELAS 6)
// --------------------------------------------------------------------------
function pilihKelasGuruNav(tingkat) {
  playSound('click');
  state.tingkatKelasGuru = tingkat;

  // Pastikan berada di tab guru & gradebook
  if (state.currentTab !== 'guru') {
    switchTab('guru');
  }
  if (state.subTabGuru !== 'gradebook') {
    pilihSubTabGuru('gradebook');
  }

  // Update styling tombol dock guru desktop
  const btnK4 = document.getElementById('nav-guru-k4');
  const btnK5 = document.getElementById('nav-guru-k5');
  const btnK6 = document.getElementById('nav-guru-k6');
  const btnProf = document.getElementById('nav-guru-profil');

  const inactiveCls = 'nav-btn nav-btn-3d px-3.5 sm:px-4 py-2 rounded-full font-title font-semibold text-xs sm:text-sm transition-all duration-200 flex items-center gap-2 text-slate-300 hover:text-white shrink-0 cursor-pointer';
  const activeCls = 'nav-btn nav-btn-3d active-tab px-4.5 sm:px-5 py-2 rounded-full font-title font-bold text-xs sm:text-sm transition-all duration-200 flex items-center gap-2 shrink-0 cursor-pointer';

  if (btnK4) btnK4.className = (tingkat === '4') ? activeCls : inactiveCls;
  if (btnK5) btnK5.className = (tingkat === '5') ? activeCls : inactiveCls;
  if (btnK6) btnK6.className = (tingkat === '6') ? activeCls : inactiveCls;
  if (btnProf) {
    if (tingkat === 'all') {
      btnProf.className = 'nav-btn nav-btn-3d active-tab px-4.5 sm:px-5 py-2 rounded-full font-title font-bold text-xs sm:text-sm transition-all duration-200 flex items-center gap-2 shrink-0 cursor-pointer';
    } else {
      btnProf.className = 'nav-btn nav-btn-3d px-3.5 sm:px-4 py-2 rounded-full font-title font-bold text-xs sm:text-sm transition-all duration-200 flex items-center gap-2 text-amber-300 hover:text-white shrink-0 cursor-pointer';
    }
  }

  // Mobile styling
  const mBtnK4 = document.getElementById('m-nav-guru-k4');
  const mBtnK5 = document.getElementById('m-nav-guru-k5');
  const mBtnK6 = document.getElementById('m-nav-guru-k6');
  const mBtnProf = document.getElementById('m-nav-guru-profil');

  if (mBtnK4) mBtnK4.className = (tingkat === '4') ? 'nav-btn-mobile flex flex-col items-center text-xs font-bold text-blue-400 scale-105' : 'nav-btn-mobile flex flex-col items-center text-xs font-semibold text-slate-400';
  if (mBtnK5) mBtnK5.className = (tingkat === '5') ? 'nav-btn-mobile flex flex-col items-center text-xs font-bold text-blue-400 scale-105' : 'nav-btn-mobile flex flex-col items-center text-xs font-semibold text-slate-400';
  if (mBtnK6) mBtnK6.className = (tingkat === '6') ? 'nav-btn-mobile flex flex-col items-center text-xs font-bold text-blue-400 scale-105' : 'nav-btn-mobile flex flex-col items-center text-xs font-semibold text-slate-400';
  if (mBtnProf) mBtnProf.className = (tingkat === 'all') ? 'nav-btn-mobile flex flex-col items-center text-xs font-bold text-amber-300 scale-105' : 'nav-btn-mobile flex flex-col items-center text-xs font-semibold text-amber-300/70';

  if (tingkat === 'all') {
    state.filterKelasGuru = 'semua';
    updateFilterKelasTabs('all');
    filterDanCariSiswa();
    showToast('Menampilkan Seluruh Siswa Pengampu Darningsih, S.T. 👩‍🏫', 'info');
  } else {
    state.filterKelasGuru = `tingkat_${tingkat}`;
    updateFilterKelasTabs(tingkat);
    filterDanCariSiswa();
    showToast(`Menampilkan Data Siswa Kelas ${tingkat} • Pengampu Darningsih, S.T. 🎓`, 'success');
  }
}
window.pilihKelasGuruNav = pilihKelasGuruNav;

function updateFilterKelasTabs(tingkat) {
  const container = document.getElementById('guru-filter-kelas-container');
  if (!container) return;

  const currentTingkat = tingkat || state.tingkatKelasGuru || '4';
  const currentFilter = state.filterKelasGuru || (currentTingkat === 'all' ? 'semua' : `tingkat_${currentTingkat}`);

  const classMap = {
    '4': ['4A', '4B', '4C', '4D', '4E'],
    '5': ['5A', '5B', '5C', '5D', '5E'],
    '6': ['6A', '6B', '6C', '6D', '6E']
  };

  const tingkatBtn = (t, label, icon) => {
    const isActive = (currentTingkat === t);
    return `<button type="button" onclick="pilihKelasGuruNav('${t}')" id="btn-tingkat-${t}" class="px-2.5 py-1 rounded-md text-xs font-title font-bold transition-all cursor-pointer flex items-center gap-1.5 ${isActive ? 'bg-indigo-600 text-white shadow-xs' : 'text-slate-600 hover:text-slate-900 hover:bg-white'}">
      ${icon ? `<i class="${icon} text-[10px]"></i>` : ''}<span>${label}</span>
    </button>`;
  };

  let html = `
    <!-- Selector Tingkat: Semua, Kelas 4, Kelas 5, Kelas 6 -->
    <div class="inline-flex items-center p-0.5 bg-slate-100 rounded-lg border border-slate-200 mr-1.5 shrink-0">
      ${tingkatBtn('all', 'Semua', 'fa-solid fa-users')}
      ${tingkatBtn('4', 'Kelas 4', 'fa-solid fa-graduation-cap')}
      ${tingkatBtn('5', 'Kelas 5', 'fa-solid fa-brain')}
      ${tingkatBtn('6', 'Kelas 6', 'fa-solid fa-school')}
    </div>
  `;

  if (currentTingkat === 'all') {
    const isSemua = (currentFilter === 'semua');
    html += `
      <button type="button" onclick="setFilterKelasGuru('semua')" id="btn-filter-kelas-semua" class="px-3 py-1.5 rounded-lg text-xs font-bold transition cursor-pointer ${isSemua ? 'bg-indigo-100 text-indigo-700 border border-indigo-300' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">Semua Siswa</button>
    `;
    const allClasses = ['4A', '4B', '4C', '4D', '4E', '5A', '5B', '5C', '5D', '5E', '6A', '6B', '6C', '6D', '6E'];
    allClasses.forEach(clsName => {
      const isSel = (currentFilter === clsName);
      html += `<button type="button" onclick="setFilterKelasGuru('${clsName}')" id="btn-filter-kelas-${clsName}" class="px-2.5 py-1.5 rounded-lg text-xs font-semibold transition cursor-pointer ${isSel ? 'bg-indigo-100 text-indigo-700 border border-indigo-300 font-bold' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">${clsName}</button>`;
    });
  } else {
    const list = classMap[currentTingkat] || ['4A', '4B', '4C', '4D', '4E'];
    const isAllTingkat = (currentFilter === `tingkat_${currentTingkat}`);
    html += `
      <span class="text-xs font-bold text-slate-400 uppercase mr-1">Tingkat ${currentTingkat}:</span>
      <button type="button" onclick="setFilterKelasGuru('tingkat_${currentTingkat}')" id="btn-filter-kelas-tingkat_${currentTingkat}" class="px-3 py-1.5 rounded-lg text-xs font-bold transition cursor-pointer ${isAllTingkat ? 'bg-indigo-100 text-indigo-700 border border-indigo-300' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">Semua Kelas ${currentTingkat}</button>
    `;
    list.forEach(clsName => {
      const isSel = (currentFilter === clsName);
      html += `<button type="button" onclick="setFilterKelasGuru('${clsName}')" id="btn-filter-kelas-${clsName}" class="px-2.5 py-1.5 rounded-lg text-xs font-semibold transition cursor-pointer ${isSel ? 'bg-indigo-100 text-indigo-700 border border-indigo-300 font-bold' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}">${clsName}</button>`;
    });
  }

  container.innerHTML = html;
}
window.updateFilterKelasTabs = updateFilterKelasTabs;

// --------------------------------------------------------------------------
// KONTROL SUB-TAB DASBOR GURU
// --------------------------------------------------------------------------
function pilihSubTabGuru(tabName) {
  try { if (typeof playSound === 'function') playSound('click'); } catch(e) {}
  try { if (typeof state !== 'undefined') state.subTabGuru = tabName; } catch(e) {}

  const tabs = ['gradebook', 'drive7k', 'galeri', 'analisis', 'cloud', 'bank-soal'];
  tabs.forEach(t => {
    const view = document.getElementById(`guru-view-${t}`);
    const btn = document.getElementById(`guru-subtab-btn-${t}`);
    if (view) {
      if (t === tabName) {
        view.classList.remove('hidden');
        view.style.removeProperty('display');
        view.style.setProperty('display', 'block', 'important');
      } else {
        view.classList.add('hidden');
        view.style.setProperty('display', 'none', 'important');
      }
    }
    if (btn) {
      if (t === tabName) {
        btn.className = 'px-4 py-2 rounded-xl text-xs font-bold font-title transition flex items-center gap-2 bg-indigo-600 text-white shadow-xs cursor-pointer';
      } else {
        btn.className = 'px-4 py-2 rounded-xl text-xs font-semibold font-title text-slate-600 hover:bg-slate-100 transition flex items-center gap-2 cursor-pointer';
      }
    }
  });

  try {
    if (tabName === 'gradebook') {
      if (typeof filterDanCariSiswa === 'function') filterDanCariSiswa();
    } else if (tabName === 'drive7k') {
      if (typeof renderMonitoringDrive7KGuru === 'function') renderMonitoringDrive7KGuru();
    } else if (tabName === 'galeri') {
      if (typeof renderGaleriGuru === 'function') renderGaleriGuru();
    } else if (tabName === 'bank-soal') {
      if (typeof renderBankSoalGuru === 'function') renderBankSoalGuru();
    } else if (tabName === 'cloud') {
      if (typeof renderTabsKelasSheet === 'function') renderTabsKelasSheet();
      if (typeof renderRingkasanKoneksiKelas === 'function') renderRingkasanKoneksiKelas();
      const inputWebhook = document.getElementById('guru-webhook-url');
      if (inputWebhook && typeof getPersistentWebhookUrl === 'function') {
        const savedWebhook = getPersistentWebhookUrl();
        if (savedWebhook) inputWebhook.value = savedWebhook;
      }
    }
  } catch(err) {
    console.warn('Subtab render execution:', err);
  }
}
window.pilihSubTabGuru = pilihSubTabGuru;

function setFilterKelasGuru(kelas) {
  playSound('click');
  state.filterKelasGuru = kelas;

  const container = document.getElementById('guru-filter-kelas-container');
  if (container) {
    container.querySelectorAll('button[id^="btn-filter-kelas-"]').forEach(btn => {
      if (btn.id === `btn-filter-kelas-${kelas}`) {
        btn.className = 'px-3 py-1.5 rounded-lg text-xs font-bold bg-indigo-100 text-indigo-700 border border-indigo-300 transition cursor-pointer';
      } else {
        btn.className = 'px-2.5 py-1.5 rounded-lg text-xs font-semibold bg-slate-100 text-slate-600 hover:bg-slate-200 transition cursor-pointer';
      }
    });
  }

  filterDanCariSiswa();
  if (state.subTabGuru === 'drive7k') {
    renderMonitoringDrive7KGuru();
  } else if (state.subTabGuru === 'galeri') {
    renderGaleriGuru();
  }

  // Jika kelas spesifik (seperti '4B') belum memiliki data di lokal, otomatis coba tarik dari Google Sheets secara aman tanpa freeze
  if (kelas && kelas !== 'semua' && !kelas.startsWith('tingkat_')) {
    const db = getStudentDatabase();
    const studentsInClass = db.filter(s => s.kelas === kelas);
    if (studentsInClass.length === 0 && typeof sinkronkanDataSiswaPerKelas === 'function') {
      if (!window._isSyncingSheets && (!window._lastAutoSyncTime || (Date.now() - window._lastAutoSyncTime > 15000))) {
        window._isSyncingSheets = true;
        window._lastAutoSyncTime = Date.now();
        sinkronkanDataSiswaPerKelas(kelas, true).then(res => {
          if (res && res.length > 0) {
            filterDanCariSiswa();
            if (state.subTabGuru === 'drive7k') renderMonitoringDrive7KGuru();
            if (state.subTabGuru === 'galeri') renderGaleriGuru();
          }
        }).catch(err => console.warn('Auto-sync kelas info:', err))
          .finally(() => { window._isSyncingSheets = false; });
      }
    }
  }
}
window.setFilterKelasGuru = setFilterKelasGuru;

