// --------------------------------------------------------------------------
// FILTER & PENCARIAN SISWA DI GRADEBOOK
// --------------------------------------------------------------------------
function filterDanCariSiswa() {
  const db = getStudentDatabase();
  const searchInput = document.getElementById('guru-cari-siswa');
  const filterKkmSelect = document.getElementById('guru-filter-kkm');
  const query = searchInput ? searchInput.value.toLowerCase().trim() : '';
  const filterKkm = filterKkmSelect ? filterKkmSelect.value : 'semua';
  const mode = state.modePenilaianGuru || 1;

  const filtered = db.filter(s => {
    if (!s) return false;
    // Filter Kelas / Tingkat (Disesuaikan dengan pengampu resmi Ibu Darningsih, S.T.)
    const activeFilter = state.filterKelasGuru || 'semua';
    if (activeFilter && activeFilter.startsWith('tingkat_')) {
      const targetTingkat = activeFilter.replace('tingkat_', '');
      const tingkatClassMap = {
        '4': ['4A', '4B', '4C', '4D', '4E'],
        '5': ['5A', '5B', '5C', '5D', '5E'],
        '6': ['6A', '6B', '6C', '6D', '6E']
      };
      const allowedClasses = tingkatClassMap[targetTingkat] || [];
      const sCls = String(s.kelas || '').toUpperCase();
      if (!allowedClasses.includes(s.kelas) && !sCls.startsWith(targetTingkat)) return false;
    } else if (activeFilter !== 'semua' && s.kelas !== activeFilter) {
      return false;
    }

    // Hitung status nilai berdasarkan mode penilaian aktif
    let skorAktif = 80;
    if (mode === 1) {
      const nilaiDrive = s.nilaiDrive !== undefined ? s.nilaiDrive : (s.driveData ? hitungNilaiDrive7Kebiasaan(s.driveData).totalSkor : 0);
      const p1 = s.nilaiPoster !== undefined ? s.nilaiPoster : (s.posterWord > 0 ? 90 : 0);
      const p2 = s.nilaiExcel !== undefined ? s.nilaiExcel : (s.excelTabel > 0 ? 88 : 0);
      skorAktif = Math.round(((s.kuisSem1 || 0) * 0.25) + (nilaiDrive * 0.25) + (p1 * 0.25) + (p2 * 0.25));
    } else if (mode === 2) {
      const p1 = s.nilaiScratch !== undefined ? s.nilaiScratch : (s.projekScratch > 0 ? 90 : 0);
      const p2 = s.nilaiRoboMind !== undefined ? s.nilaiRoboMind : (s.misiRobo > 0 ? 88 : 0);
      skorAktif = Math.round(((s.kuisSem2 || 0) * 0.3) + (p1 * 0.35) + (p2 * 0.35));
    } else {
      const nilaiDrive = s.nilaiDrive !== undefined ? s.nilaiDrive : (s.driveData ? hitungNilaiDrive7Kebiasaan(s.driveData).totalSkor : 0);
      const p1_s1 = s.nilaiPoster !== undefined ? s.nilaiPoster : (s.posterWord > 0 ? 90 : 0);
      const p2_s1 = s.nilaiExcel !== undefined ? s.nilaiExcel : (s.excelTabel > 0 ? 88 : 0);
      const nilaiSem1 = Math.round(((s.kuisSem1 || 0) * 0.25) + (nilaiDrive * 0.25) + (p1_s1 * 0.25) + (p2_s1 * 0.25));
      const p1_s2 = s.nilaiScratch !== undefined ? s.nilaiScratch : (s.projekScratch > 0 ? 90 : 0);
      const p2_s2 = s.nilaiRoboMind !== undefined ? s.nilaiRoboMind : (s.misiRobo > 0 ? 88 : 0);
      const nilaiSem2 = Math.round(((s.kuisSem2 || 0) * 0.3) + (p1_s2 * 0.35) + (p2_s2 * 0.35));
      skorAktif = Math.round((nilaiSem1 + nilaiSem2) / 2);
    }

    // Filter KKM
    if (filterKkm === 'tuntas') {
      if (skorAktif < 80) return false;
    } else if (filterKkm === 'remedial') {
      if (skorAktif >= 80) return false;
    }

    // Search query
    if (query) {
      const matchNama = (s.nama || '').toString().toLowerCase().includes(query);
      const matchAbsen = (s.absen || '').toString().includes(query);
      const matchNis = (s.nis || '').toString().toLowerCase().includes(query);
      if (!matchNama && !matchAbsen && !matchNis) return false;
    }
    return true;
  });

  // Urutkan siswa secara ketat dan konsisten berdasarkan nomor urut absen (1, 2, 3...)
  const sortedFiltered = urutkanSiswaSesuaiNomorAbsen(filtered);

  renderTabelGradebook(sortedFiltered, db.length);
}
window.filterDanCariSiswa = filterDanCariSiswa;

