function bukaModalPanduanSheets() {
  try { playSound('click'); } catch (e) {}
  const modal = document.getElementById('modal-panduan-sheets');
  if (modal) {
    modal.classList.remove('hidden');
    modal.style.removeProperty('display');
    modal.style.setProperty('display', 'flex', 'important');
    modal.style.setProperty('pointer-events', 'auto', 'important');
    modal.style.setProperty('visibility', 'visible', 'important');
    modal.style.setProperty('z-index', '999999', 'important');
  }
}
window.bukaModalPanduanSheets = bukaModalPanduanSheets;

function tutupModalPanduanSheets() {
  try { playSound('click'); } catch (e) {}
  const modal = document.getElementById('modal-panduan-sheets');
  if (modal) {
    modal.classList.add('hidden');
    modal.style.setProperty('display', 'none', 'important');
    modal.style.setProperty('pointer-events', 'none', 'important');
    modal.style.setProperty('visibility', 'hidden', 'important');
    modal.style.setProperty('z-index', '-9999', 'important');
  }
}
window.tutupModalPanduanSheets = tutupModalPanduanSheets;

function salinKodeAppsScript() {
  playSound('click');
  const scriptCode = `// ========================================================
// GOOGLE APPS SCRIPT: EDUCODE LMS KELAS 4 - SDS CINTA KASIH TZU CHI
// Tab Wajib: "DATA SISWA LMS"
// Tab Rekap: "REKAP NILAI SISWA"
// ========================================================

function doGet(e) {
  var ss = SpreadsheetApp.getActiveSpreadsheet();
  var sheet = ss.getSheetByName("DATA SISWA LMS");
  
  if (!sheet) {
    return ContentService.createTextOutput(JSON.stringify({
      status: "error",
      message: "Sheet 'DATA SISWA LMS' tidak ditemukan!"
    })).setMimeType(ContentService.MimeType.JSON);
  }
  
  var data = sheet.getDataRange().getValues();
  if (data.length <= 1) {
    return ContentService.createTextOutput(JSON.stringify({
      status: "success",
      students: []
    })).setMimeType(ContentService.MimeType.JSON);
  }
  
  var headers = data[0].map(function(h) { return h.toString().toLowerCase().trim(); });
  var nisIdx = headers.indexOf("nis");
  var namaIdx = headers.indexOf("nama");
  if (namaIdx === -1) namaIdx = headers.indexOf("nama siswa");
  var kelasIdx = headers.indexOf("kelas");
  var absenIdx = headers.indexOf("absen");
  if (absenIdx === -1) absenIdx = headers.indexOf("no. absen");
  if (absenIdx === -1) absenIdx = headers.indexOf("no absen");
  
  if (nisIdx === -1) nisIdx = 0;
  if (namaIdx === -1) namaIdx = 1;
  if (kelasIdx === -1) kelasIdx = 2;
  if (absenIdx === -1) absenIdx = 3;
  
  var students = [];
  for (var i = 1; i < data.length; i++) {
    var row = data[i];
    var nis = row[nisIdx] ? row[nisIdx].toString().trim() : "";
    if (nis) {
      students.push({
        id: "STD-" + (row[kelasIdx] || "4") + "-" + nis,
        nis: nis,
        nama: row[namaIdx] ? row[namaIdx].toString().trim() : "Siswa " + nis,
        kelas: row[kelasIdx] ? row[kelasIdx].toString().trim() : "4A",
        absen: row[absenIdx] ? row[absenIdx].toString().trim() : "01"
      });
    }
  }
  
  var queryNis = e && e.parameter && e.parameter.nis ? e.parameter.nis.toString().trim() : null;
  if (queryNis) {
    var match = students.filter(function(s) { return s.nis.toLowerCase() === queryNis.toLowerCase(); });
    return ContentService.createTextOutput(JSON.stringify({
      status: match.length > 0 ? "found" : "not_found",
      student: match.length > 0 ? match[0] : null
    })).setMimeType(ContentService.MimeType.JSON);
  }
  
  return ContentService.createTextOutput(JSON.stringify({
    status: "success",
    count: students.length,
    students: students
  })).setMimeType(ContentService.MimeType.JSON);
}

function doPost(e) {
  try {
    var ss = SpreadsheetApp.getActiveSpreadsheet();
    var payload = JSON.parse(e.postData.contents);
    
    // 1. Rekam ke Tab Buku Nilai & Aktivitas Siswa
    var sheetRekap = ss.getSheetByName("REKAP NILAI SISWA");
    if (!sheetRekap) {
      sheetRekap = ss.insertSheet("REKAP NILAI SISWA");
      sheetRekap.appendRow(["Waktu", "NIS", "Nama Siswa", "Kelas", "No. Absen", "Aktivitas", "Nilai", "Status KKM", "Keterangan"]);
    }
    
    sheetRekap.appendRow([
      new Date(),
      payload.nis || "-",
      payload.nama || "-",
      payload.kelas || "-",
      payload.absen || "-",
      payload.event || payload.aktivitas || "Latihan",
      payload.nilai !== undefined ? payload.nilai : (payload.kuisSem1 || payload.kuisSem2 || 0),
      payload.statusKkm || "Tuntas",
      payload.title || payload.keterangan || "-"
    ]);

    // 2. SIMPAN BERKAS GAMBAR ASLI KE GOOGLE DRIVE
    var driveFileUrl = "-";
    if (payload.image && typeof payload.image === "string" && payload.image.indexOf("base64,") !== -1) {
      try {
        var base64Data = payload.image.split("base64,")[1];
        var decoded = Utilities.base64Decode(base64Data);
        var isJpeg = payload.image.indexOf("image/jpeg") !== -1;
        var ext = isJpeg ? ".jpg" : ".png";
        var mime = isJpeg ? "image/jpeg" : "image/png";
        var rawNama = payload.fileName || payload.title || ("Karya_" + (payload.nama || "Siswa"));
        var namaFile = rawNama.replace(/[^a-zA-Z0-9_\- ]/g, "").trim() + ext;
        var blob = Utilities.newBlob(decoded, mime, namaFile);

        // Cari atau buat Folder Utama "Karya Siswa - EduCode AI" di Google Drive
        var mainFolderName = "Karya Siswa - EduCode AI";
        var folders = DriveApp.getFoldersByName(mainFolderName);
        var mainFolder = folders.hasNext() ? folders.next() : DriveApp.createFolder(mainFolderName);

        // Buat subfolder kelas (misal: "Kelas 4A")
        var subFolderName = payload.kelas ? ("Kelas " + payload.kelas) : "Kelas 4";
        var subFolders = mainFolder.getFoldersByName(subFolderName);
        var targetFolder = subFolders.hasNext() ? subFolders.next() : mainFolder.createFolder(subFolderName);

        var file = targetFolder.createFile(blob);
        file.setSharing(DriveApp.Access.ANYONE_WITH_LINK, DriveApp.Permission.VIEW);
        driveFileUrl = file.getUrl();
      } catch (errDrive) {
        driveFileUrl = "Gagal simpan Drive: " + errDrive.toString();
      }
    }

    // 3. Rekam Portofolio & Link Google Drive ke Tab PORTOFOLIO GOOGLE DRIVE
    if (payload.event === "simpan_poster" || payload.event === "simpan_slot_drive" || payload.type === "poster" || payload.type === "drive_7kebiasaan" || payload.image) {
      var sheetKarya = ss.getSheetByName("PORTOFOLIO GOOGLE DRIVE");
      if (!sheetKarya) {
        sheetKarya = ss.insertSheet("PORTOFOLIO GOOGLE DRIVE");
        sheetKarya.appendRow(["Waktu", "NIS", "Nama Siswa", "Kelas", "Judul Karya / Slot", "Tipe", "Link Google Drive"]);
      }
      sheetKarya.appendRow([
        new Date(),
        payload.nis || "-",
        payload.nama || "-",
        payload.kelas || "-",
        payload.title || payload.habitKey || "Karya Siswa",
        payload.type || "Gambar",
        driveFileUrl
      ]);
    }

    // 4. Update otomatis nilai langsung ke baris siswa di Tab "DATA SISWA LMS" (Satu File)
    var sheetData = ss.getSheetByName("DATA SISWA LMS");
    if (sheetData && payload.nis) {
      try {
        var dValues = sheetData.getDataRange().getValues();
        if (dValues.length > 1) {
          var dHeaders = dValues[0].map(function(h) { return h.toString().toLowerCase().trim(); });
          var dNisIdx = dHeaders.indexOf("nis");
          if (dNisIdx !== -1) {
            var targetRow = -1;
            for (var r = 1; r < dValues.length; r++) {
              if (dValues[r][dNisIdx] && dValues[r][dNisIdx].toString().trim() === payload.nis.toString().trim()) {
                targetRow = r + 1; // 1-based index di Spreadsheet
                break;
              }
            }

            if (targetRow !== -1) {
              var colKuis1 = dHeaders.indexOf("kuis sem 1");
              var colPoster = dHeaders.indexOf("poster word");
              var colExcel = dHeaders.indexOf("tabel excel");
              var colDrive = dHeaders.indexOf("drive 7 kebiasaan");
              var colKkm = dHeaders.indexOf("status kkm");

              var curLastCol = sheetData.getLastColumn();
              if (colKuis1 === -1) { sheetData.getRange(1, ++curLastCol).setValue("Kuis Sem 1"); colKuis1 = curLastCol - 1; }
              if (colPoster === -1) { sheetData.getRange(1, ++curLastCol).setValue("Poster Word"); colPoster = curLastCol - 1; }
              if (colExcel === -1) { sheetData.getRange(1, ++curLastCol).setValue("Tabel Excel"); colExcel = curLastCol - 1; }
              if (colDrive === -1) { sheetData.getRange(1, ++curLastCol).setValue("Drive 7 Kebiasaan"); colDrive = curLastCol - 1; }
              if (colKkm === -1) { sheetData.getRange(1, ++curLastCol).setValue("Status KKM"); colKkm = curLastCol - 1; }

              if (payload.event === "kuis" || payload.kuisSem1 !== undefined) {
                sheetData.getRange(targetRow, colKuis1 + 1).setValue(payload.nilai !== undefined ? payload.nilai : payload.kuisSem1);
              }
              if (payload.event === "simpan_poster" || payload.type === "poster") {
                sheetData.getRange(targetRow, colPoster + 1).setValue(payload.nilai || 90);
              }
              if (payload.event === "simpan_excel" || payload.type === "excel") {
                sheetData.getRange(targetRow, colExcel + 1).setValue(payload.nilai || 88);
              }
              if (payload.event === "simpan_slot_drive" || payload.type === "drive_7kebiasaan") {
                sheetData.getRange(targetRow, colDrive + 1).setValue((payload.koleksiDrive !== undefined ? payload.koleksiDrive : "Update") + "/7 Gambar");
              }
              if (payload.statusKkm) {
                sheetData.getRange(targetRow, colKkm + 1).setValue(payload.statusKkm);
              }
            }
          }
        }
      } catch (eUp) {}
    }
    
    return ContentService.createTextOutput(JSON.stringify({
      status: "success",
      message: "Data & Berkas Gambar berhasil disimpan di Google Drive & Google Sheets!",
      driveUrl: driveFileUrl
    })).setMimeType(ContentService.MimeType.JSON);
  } catch (err) {
    return ContentService.createTextOutput(JSON.stringify({
      status: "error",
      message: err.toString()
    })).setMimeType(ContentService.MimeType.JSON);
  }
}`;

  if (navigator.clipboard) {
    navigator.clipboard.writeText(scriptCode).then(() => {
      showToast('Kode Google Apps Script berhasil disalin ke clipboard! 📋', 'success');
      alert('Kode Google Apps Script telah disalin!\n\nCara pasang:\n1. Di Google Sheets, klik Extensions > Apps Script.\n2. Tempel kode ini lalu Deploy > New deployment > Web app (Anyone can access).\n3. Salin URL Web app-nya ke aplikasi.');
    }).catch(() => {
      prompt('Salin manual skrip ini:', scriptCode);
    });
  } else {
    prompt('Salin manual skrip ini:', scriptCode);
  }
}

function simpanWebhookGuruForm() {
  const input = document.getElementById('guru-webhook-url');
  if (!input) return;
  const val = input.value.trim();
  if (val) {
    savePersistentWebhookUrl(val);
    playSound('success');
    showToast('URL Webhook Google Apps Script berhasil disimpan permanen! 🔗', 'success');
  } else {
    const existing = getPersistentWebhookUrl();
    if (existing) {
      if (confirm('Apakah Anda yakin ingin menghapus / mengosongkan URL Webhook Google Apps Script?')) {
        savePersistentWebhookUrl('');
        showToast('URL Webhook Google Apps Script dikosongkan.', 'info');
      } else {
        input.value = existing;
      }
    } else {
      savePersistentWebhookUrl('');
      showToast('URL Webhook Google Apps Script dikosongkan.', 'info');
    }
  }
}
window.simpanWebhookGuruForm = simpanWebhookGuruForm;

function ujiKirimWebhookGuru() {
  playSound('click');
  const input = document.getElementById('guru-webhook-url');
  let url = input ? input.value.trim() : '';
  if (!url) {
    url = getPersistentWebhookUrl();
  }

  if (!url) {
    playSound('warning');
    if (input) {
      input.classList.add('border-rose-500', 'animate-shake');
      setTimeout(() => input.classList.remove('animate-shake', 'border-rose-500'), 600);
      input.focus();
    }
    showToast('⚠️ Masukkan Link Webhook Google Apps Script terlebih dahulu di kolom sebelah kiri! (Klik "Cara Pasang" untuk melihat panduan)', 'warning');
    return;
  }

  // Otomatis simpan URL jika ada di input
  savePersistentWebhookUrl(url);

  showToast('✈️ Mengirim data uji coba ke Google Sheets... Periksa tab "REKAP NILAI SISWA" di Spreadsheet Anda 📊', 'info');
  kirimKeWebhookSheets({
    event: 'uji_coba_koneksi',
    nis: '4101',
    nama: 'Aditya Pratama (Uji Coba)',
    kelas: '4A',
    absen: '01',
    kuisSem1: 100,
    statusKkm: 'Tuntas',
    timestamp: new Date().toISOString()
  });
}
window.ujiKirimWebhookGuru = ujiKirimWebhookGuru;

function kirimKeWebhookSheets(payload) {
  const url = getPersistentWebhookUrl();
  if (!url) return;

  fetch(url, {
    method: 'POST',
    mode: 'no-cors',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(payload)
  }).then(() => {
    playSound('success');
    showToast('✅ Data uji coba terkirim ke Google Sheets! Silakan periksa Spreadsheet Anda.', 'success');
  }).catch(err => {
    console.warn('Gagal sinkronisasi Google Sheets:', err);
    playSound('error');
    showToast('❌ Gagal mengirim ke Webhook. Pastikan izin Deploy Web App disetel "Anyone" (Siapa Saja).', 'error');
  });
}
