window.addEventListener('load', function() {
  // Inisialisasi otomatis Firebase Realtime Cloud Sync
  try {
    if (typeof initFirebaseClient === 'function') {
      initFirebaseClient();
    }
  } catch (eFbInit) {}

  try {
    if (typeof isTeacherSessionActive === 'function' && isTeacherSessionActive()) {
      state.isGuruLoggedIn = true;
      setHeaderNavMode('guru');
      switchTab('guru');
      var tabB = document.getElementById('tab-beranda');
      var tabG = document.getElementById('tab-guru');
      if (tabB) { tabB.classList.add('hidden'); tabB.style.setProperty('display', 'none', 'important'); }
      if (tabG) { tabG.classList.remove('hidden'); tabG.style.removeProperty('display'); tabG.style.setProperty('display', 'block', 'important'); }
      if (typeof pilihKelasGuruNav === 'function') {
        pilihKelasGuruNav(state.tingkatKelasGuru || '4');
      }
      if (typeof renderDasborGuru === 'function') {
        renderDasborGuru();
      }
    } else {
      const student = getActiveStudentProfile();
      if (student) {
        // Pasang listener realtime live sync untuk siswa aktif ini
        try {
          if (typeof pasangRealtimeSyncDrive === 'function') {
            pasangRealtimeSyncDrive(student.nis || student.id);
          }
          if (typeof sinkronkanKaryaSiswaDariCloud === 'function') {
            sinkronkanKaryaSiswaDariCloud(student);
          }
        } catch (eSyncEarly) {}

        const isKelas5 = String(student.kelas || '').includes('5');
        if (isKelas5) {
          setHeaderNavMode('kelas5');
          muatProfilSiswa();
          switchTab('petualangan5');
        } else {
          setHeaderNavMode('sem1');
          muatProfilSiswa();
          let savedTab = 'beranda';
          try { savedTab = localStorage.getItem('educode_student_active_tab_v1') || 'beranda'; } catch (eTab) {}
          if (!savedTab || savedTab === 'guru' || savedTab === 'petualangan5') savedTab = 'beranda';
          switchTab(savedTab);
        }
      } else {
        setHeaderNavMode('utama');
        switchTab('beranda');
      }
    }
  } catch (eLoad) {}
  if (typeof updateSemesterAccessUI === 'function') {
    updateSemesterAccessUI();
  }
  if (typeof updateScrollNavVisibility === 'function') {
    updateScrollNavVisibility();
  }

  // Pasang listener pengaman ganda untuk seluruh tombol Keluar Guru & Siswa
  try {
    const btnKeluarGuru1 = document.getElementById('nav-guru-keluar');
    if (btnKeluarGuru1) btnKeluarGuru1.addEventListener('click', keluarModeGuru);
    const btnKeluarGuru2 = document.getElementById('m-nav-guru-keluar');
    if (btnKeluarGuru2) btnKeluarGuru2.addEventListener('click', keluarModeGuru);
    const btnKeluarSiswa1 = document.getElementById('btn-welcome-logout');
    if (btnKeluarSiswa1) btnKeluarSiswa1.addEventListener('click', konfirmasiKeluarSiswa);
    const btnKeluarSiswa2 = document.getElementById('btn-rapor-keluar');
    if (btnKeluarSiswa2) btnKeluarSiswa2.addEventListener('click', konfirmasiKeluarSiswa);
    const btnLoginGuru = document.getElementById('btn-main-login-guru');
    if (btnLoginGuru) btnLoginGuru.onclick = function(e) { if (typeof window.aksiKlikTombolGuruUtama === 'function') { window.aksiKlikTombolGuruUtama(e); } else { bukaModalLoginGuru(); } };
    const btnLoginSiswa = document.getElementById('btn-welcome-login');
    if (btnLoginSiswa) btnLoginSiswa.addEventListener('click', bukaPilihSiswaCepat);
  } catch (eBind) {}
});

