// ========================================================
// INTEGRASI SERVER CLOUD DATABASE (GOOGLE FIREBASE)
// Firestore (NoSQL Document DB) + Cloud Storage (Asset Binary)
// Menjamin keamanan data karya ~200 siswa antar PC Lab & restart
// ========================================================

const FIREBASE_CONFIG_KEY = 'educode_firebase_config_v1';
const FIREBASE_LAST_SYNC_KEY = 'educode_firebase_last_sync_v1';
let firebaseAppInstance = null;
let firebaseFirestoreInstance = null;
let firebaseStorageInstance = null;
let isFirebaseConnected = false;

// Konfigurasi Resmi Proyek Firebase SDS Cinta Kasih Tzu Chi (sd-tzuchi-kelas4)
const DEFAULT_FIREBASE_CONFIG = {
  apiKey: "AIzaSyDs1XJQTKymX0YG5g28yi9ImSLcn4RtZ5Y",
  authDomain: "sd-tzuchi-kelas4.firebaseapp.com",
  projectId: "sd-tzuchi-kelas4",
  storageBucket: "sd-tzuchi-kelas4.firebasestorage.app",
  messagingSenderId: "1083820511307",
  appId: "1:1083820511307:web:4bd4f5933d6c061f1b7dce",
  measurementId: "G-KWEHGW5C0X"
};
window.DEFAULT_FIREBASE_CONFIG = DEFAULT_FIREBASE_CONFIG;

// Parser fleksibel super tangguh: menerima salinan kode SDK modul, import statements, const firebaseConfig = {...}, atau format JSON murni
function parseFirebaseConfig(raw) {
  if (!raw || typeof raw !== 'string') return DEFAULT_FIREBASE_CONFIG;
  const str = raw.trim();
  if (!str) return DEFAULT_FIREBASE_CONFIG;

  // Helper extractor regex yang tahan terhadap kutip ganda, kutip tunggal, spasi, komentar, dan baris baru
  const extractVal = (key) => {
    const re = new RegExp(`['"]?${key}['"]?\\s*:\\s*['"]([^'"]+)['"]`, 'i');
    const m = str.match(re);
    return m ? m[1].trim() : '';
  };

  const apiKey = extractVal('apiKey');
  const projectId = extractVal('projectId');
  const authDomain = extractVal('authDomain') || (projectId ? `${projectId}.firebaseapp.com` : '');
  const storageBucket = extractVal('storageBucket') || (projectId ? `${projectId}.firebasestorage.app` : '');
  const messagingSenderId = extractVal('messagingSenderId');
  const appId = extractVal('appId');
  const measurementId = extractVal('measurementId');

  if (apiKey && projectId) {
    const res = { apiKey, projectId, authDomain, storageBucket };
    if (messagingSenderId) res.messagingSenderId = messagingSenderId;
    if (appId) res.appId = appId;
    if (measurementId) res.measurementId = measurementId;
    return res;
  }

  // Fallback jika dimasukkan dalam format JSON murni
  try {
    const jsonMatch = str.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      const obj = JSON.parse(jsonMatch[0]);
      if (obj && obj.apiKey && (obj.projectId || obj.authDomain)) {
        return obj;
      }
    }
  } catch (e) {}

  return DEFAULT_FIREBASE_CONFIG;
}
window.parseFirebaseConfig = parseFirebaseConfig;

// Loader Dinamis Asinkron: Memuat Firebase SDKs HANYA saat diperlukan (Non-blocking, anti-lag)
let _firebaseSdkLoadingPromise = null;
function loadFirebaseSDKs() {
  if (typeof window.firebase !== 'undefined' && window.firebase.initializeApp) {
    return Promise.resolve(true);
  }
  if (_firebaseSdkLoadingPromise) return _firebaseSdkLoadingPromise;

  _firebaseSdkLoadingPromise = new Promise((resolve) => {
    const urls = [
      'https://www.gstatic.com/firebasejs/10.14.1/firebase-app-compat.js',
      'https://www.gstatic.com/firebasejs/10.14.1/firebase-firestore-compat.js',
      'https://www.gstatic.com/firebasejs/10.14.1/firebase-storage-compat.js'
    ];
    let loadedCount = 0;
    let finished = false;

    const timer = setTimeout(() => {
      if (!finished) {
        finished = true;
        resolve(typeof window.firebase !== 'undefined');
      }
    }, 4500);

    const checkDone = () => {
      loadedCount++;
      if (loadedCount >= urls.length && !finished) {
        finished = true;
        clearTimeout(timer);
        resolve(true);
      }
    };

    urls.forEach(u => {
      if (document.querySelector(`script[src="${u}"]`)) {
        checkDone();
        return;
      }
      const s = document.createElement('script');
      s.src = u;
      s.async = true;
      s.onload = checkDone;
      s.onerror = () => {
        if (!finished) {
          finished = true;
          clearTimeout(timer);
          resolve(false);
        }
      };
      document.head.appendChild(s);
    });
  });

  return _firebaseSdkLoadingPromise;
}
window.loadFirebaseSDKs = loadFirebaseSDKs;

// Inisialisasi Firebase Client
function initFirebaseClient(customConfig = null) {
  try {
    if (typeof window.firebase === 'undefined') {
      isFirebaseConnected = false;
      return false;
    }

    let config = customConfig;
    if (!config) {
      const saved = localStorage.getItem(FIREBASE_CONFIG_KEY);
      if (saved) {
        config = parseFirebaseConfig(saved);
      }
      if (!config || !config.apiKey || !config.projectId) {
        config = {
          apiKey: "AIzaSyDs1XJQTKymX0YG5g28yi9ImSLcn4RtZ5Y",
          authDomain: "sd-tzuchi-kelas4.firebaseapp.com",
          projectId: "sd-tzuchi-kelas4",
          storageBucket: "sd-tzuchi-kelas4.firebasestorage.app",
          messagingSenderId: "1083820511307",
          appId: "1:1083820511307:web:4bd4f5933d6c061f1b7dce",
          measurementId: "G-KWEHGW5C0X"
        };
      }
    }

    // Inisialisasi Firebase App
    if (!firebase.apps || firebase.apps.length === 0) {
      firebaseAppInstance = firebase.initializeApp(config);
    } else {
      firebaseAppInstance = firebase.apps[0];
    }

    if (firebase.firestore) {
      firebaseFirestoreInstance = firebase.firestore();
    }
    if (firebase.storage) {
      firebaseStorageInstance = firebase.storage();
    }

    // Otomatis aktifkan isFirebaseConnected jika SDK dan config valid (kecuali jika user memilih mode offline lokal)
    const isExplicitlyDisabled = localStorage.getItem('educode_firebase_enabled_v1') === 'false';
    isFirebaseConnected = !isExplicitlyDisabled;
    perbaruiStatusFirebaseUI(config);
    return true;
  } catch (err) {
    console.error('Inisialisasi Firebase gagal:', err);
    isFirebaseConnected = false;
    perbaruiStatusFirebaseUI();
    return false;
  }
}
window.initFirebaseClient = initFirebaseClient;

