// SYNC ENGINE: UNGGAH & UNDUH KARYA SISWA KE CLOUD
// ========================================================

// 1. Unggah Poster Siswa ke Firebase Storage & Firestore
async function unggahPosterKeCloud(posterItem) {
  if (!isFirebaseConnected || !firebaseFirestoreInstance) return;

  try {
    const studentNis = posterItem.studentNis || (posterItem.docData && posterItem.docData.studentNis) || 'umum';
    let finalImageUrl = posterItem.image;

    // Jika Storage aktif dan posterItem.image adalah base64 PNG, upload ke Firebase Storage
    if (firebaseStorageInstance && typeof posterItem.image === 'string' && posterItem.image.startsWith('data:image/')) {
      try {
        const storageRef = firebaseStorageInstance.ref();
        const posterFileRef = storageRef.child(`posters/${studentNis}/${posterItem.id}.png`);
        await posterFileRef.putString(posterItem.image, 'data_url');
        finalImageUrl = await posterFileRef.getDownloadURL();
      } catch (eStorage) {
        console.warn('Upload gambar poster ke Firebase Storage dilewati (fallback base64 di Firestore):', eStorage);
      }
    }

    const cloudPayload = {
      id: posterItem.id,
      title: posterItem.title,
      date: posterItem.date,
      timestamp: posterItem.timestamp || Date.now(),
      author: posterItem.author || '',
      studentName: posterItem.studentName || '',
      studentClass: posterItem.studentClass || 'Kelas 4',
      studentNis: studentNis,
      elementsCount: posterItem.elementsCount || 0,
      image: finalImageUrl,
      docData: posterItem.docData || null,
      updatedAt: (typeof firebase !== 'undefined' && firebase.firestore && firebase.firestore.FieldValue)
        ? firebase.firestore.FieldValue.serverTimestamp()
        : Date.now()
    };

    // Simpan ke collection 'karya_posters'
    await firebaseFirestoreInstance.collection('karya_posters').doc(posterItem.id).set(cloudPayload, { merge: true });

    const nowStr = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
    localStorage.setItem(FIREBASE_LAST_SYNC_KEY, nowStr);
    perbaruiStatusFirebaseUI();
  } catch (err) {
    console.warn('Gagal mengunggah poster ke Firebase Cloud:', err);
  }
}
window.unggahPosterKeCloud = unggahPosterKeCloud;

// 2. Unggah Drive 7 Kebiasaan Siswa ke Firestore (Realtime Sync)
async function unggahDriveKeCloud(data) {
  if (!firebaseFirestoreInstance) {
    if (typeof initFirebaseClient === 'function') initFirebaseClient();
  }
  if (!isFirebaseConnected || !firebaseFirestoreInstance) return;

  try {
    const activeStudent = (typeof getActiveStudentProfile === 'function') ? getActiveStudentProfile() : null;
    const studentNis = activeStudent ? (activeStudent.nis || activeStudent.id) : 'global';

    const payload = {
      studentNis: studentNis,
      studentName: activeStudent ? activeStudent.nama : 'Umum',
      studentClass: activeStudent ? activeStudent.kelas : 'Kelas 4',
      driveData: JSON.stringify(data),
      points: (typeof state !== 'undefined' && state.userPoints) ? state.userPoints : 0,
      updatedAt: Date.now()
    };

    await firebaseFirestoreInstance.collection('student_drives').doc(String(studentNis)).set(payload, { merge: true });
    
    const nowStr = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
    localStorage.setItem(FIREBASE_LAST_SYNC_KEY, nowStr);
    perbaruiStatusFirebaseUI();
  } catch (err) {
    console.warn('Gagal mengunggah Drive ke Firebase Cloud:', err);
  }
}
window.unggahDriveKeCloud = unggahDriveKeCloud;

// 2B. Listener Sinkronisasi Realtime Firestore Antar-Komputer (Multi-Device Live Sync)
let _driveRealtimeUnsubscribe = null;
let _currentSubscribedNis = null;

function pasangRealtimeSyncDrive(studentNis) {
  if (!studentNis) return;
  if (!firebaseFirestoreInstance) {
    if (typeof initFirebaseClient === 'function') initFirebaseClient();
  }
  if (!isFirebaseConnected || !firebaseFirestoreInstance) return;

  const targetId = String(studentNis);
  if (_driveRealtimeUnsubscribe && _currentSubscribedNis === targetId) {
    return; // Sudah tersambung ke listener realtime
  }
  if (_driveRealtimeUnsubscribe) {
    try { _driveRealtimeUnsubscribe(); } catch (e) {}
    _driveRealtimeUnsubscribe = null;
  }

  _currentSubscribedNis = targetId;
  try {
    _driveRealtimeUnsubscribe = firebaseFirestoreInstance.collection('student_drives').doc(targetId)
      .onSnapshot((doc) => {
        if (!doc.exists) return;
        const cloudData = doc.data();
        if (!cloudData || !cloudData.driveData) return;
        try {
          const parsed = JSON.parse(cloudData.driveData);
          if (parsed && typeof parsed === 'object') {
            const driveKey = getDriveStorageKey();
            const localRaw = localStorage.getItem(driveKey);
            const localParsed = localRaw ? JSON.parse(localRaw) : {};

            // Penggabungan Cerdas (Auto-Merge): gabungkan data cloud dengan data lokal
            const merged = { ...localParsed, ...parsed };
            const isDiff = JSON.stringify(merged) !== localRaw;
            if (isDiff) {
              localStorage.setItem(driveKey, JSON.stringify(merged));
              if (cloudData.points !== undefined && typeof state !== 'undefined' && state.userPoints < cloudData.points) {
                state.userPoints = cloudData.points;
                try {
                  const ptsEl = document.getElementById('user-points');
                  if (ptsEl) ptsEl.innerText = state.userPoints;
                } catch (ePts) {}
              }
              const grid = document.getElementById('drive-7kebiasaan-grid');
              if (grid && state.currentTab === 'praktik') {
                renderDrive7KebiasaanGrid();
                showToast('⚡ Sinkronisasi realtime: Gambar terbaru dari komputer lain berhasil dimuat!', 'success');
              }
            }
          }
        } catch (eParse) {}
      }, (err) => {
        console.warn('Realtime listener error:', err);
      });
  } catch (err) {
    console.warn('Gagal pasang realtime listener:', err);
  }
}
window.pasangRealtimeSyncDrive = pasangRealtimeSyncDrive;

// 2C. Tombol Paksa Sinkronisasi Drive Cloud Manual & Auto-Merge Cerdas Antar-Komputer
async function paksaSinkronDriveManual() {
  playSound('click');
  showToast('⚡ Menguji koneksi Cloud Firebase & menyinkronkan gambar...', 'info');

  if (!firebaseFirestoreInstance) {
    if (typeof initFirebaseClient === 'function') initFirebaseClient();
  }

  if (!firebaseFirestoreInstance) {
    alert('⚠️ Firebase SDK belum siap. Periksa koneksi internet komputer Anda.');
    return;
  }

  const activeStudent = (typeof getActiveStudentProfile === 'function') ? getActiveStudentProfile() : null;
  const studentNis = activeStudent ? (activeStudent.nis || activeStudent.id) : '3000';
  const targetId = String(studentNis);

  try {
    // 1. Ambil data lokal saat ini
    const driveKey = getDriveStorageKey(activeStudent);
    const localRaw = localStorage.getItem(driveKey);
    let localData = {};
    try { localData = localRaw ? JSON.parse(localRaw) : {}; } catch (e) { localData = {}; }

    // 2. Baca data dari cloud Firestore
    const docRef = firebaseFirestoreInstance.collection('student_drives').doc(targetId);
    const docSnap = await docRef.get();

    let cloudDrive = {};
    if (docSnap.exists) {
      const cData = docSnap.data();
      if (cData && cData.driveData) {
        try { cloudDrive = JSON.parse(cData.driveData); } catch (e) {}
      }
    }

    // 3. Gabungkan kedua sisi (merge cerdas kedua komputer)
    const merged = { ...cloudDrive, ...localData };

    // 4. Simpan hasil gabungan kembali ke cloud agar komputer lain bisa menariknya
    const payload = {
      studentNis: targetId,
      studentName: activeStudent ? activeStudent.nama : 'Pelajar Uji Coba',
      studentClass: activeStudent ? activeStudent.kelas : '4A',
      driveData: JSON.stringify(merged),
      points: (typeof state !== 'undefined' && state.userPoints) ? state.userPoints : 0,
      updatedAt: Date.now()
    };

    await docRef.set(payload, { merge: true });

    // 5. Simpan ke local storage komputer ini
    localStorage.setItem(driveKey, JSON.stringify(merged));
    renderDrive7KebiasaanGrid();

    playSound('fanfare');
    const totalGambar = Object.keys(merged).filter(k => (typeof DRIVE_7KEBIASAAN_CONFIG !== 'undefined') && DRIVE_7KEBIASAAN_CONFIG.some(c => c.key === k)).length;
    alert(`🎉 SINKRONISASI CLOUD BERHASIL!\n\nKoleksi gambar komputer ini dan cloud telah digabungkan secara lengkap (${totalGambar} dari 7 gambar).\n\nSekarang buka komputer kedua dan klik tombol "⚡ Sinkron Cloud", maka semua gambar akan langsung sama persis! ✨`);
    showToast(`✅ Sinkronisasi Cloud sukses! Total ${totalGambar} gambar aktif.`, 'success');
  } catch (err) {
    console.error('Error manual sync:', err);
    if (err && (err.code === 'permission-denied' || (err.message && err.message.toLowerCase().includes('permission')))) {
      alert(
        `⚠️ AKSES FIREBASE CLOUD DITOLAK (Permission Denied)!\n\n` +
        `Hal ini terjadi karena di Firebase Console aturan "Rules" belum diubah ke "allow read, write: if true;".\n\n` +
        `Cara Memperbaikinya Sangat Mudah:\n` +
        `1. Buka tab "Rules" di Firebase Console (di sebelah tab Data).\n` +
        `2. Ganti kata "if false;" menjadi "if true;".\n` +
        `3. Klik tombol biru "Publish" di kanan atas.\n\n` +
        `Setelah itu, klik tombol [⚡ Sinkron Cloud] ini lagi, dan semua gambar akan langsung tersinkron di kedua komputer!`
      );
    } else {
      alert(`⚠️ Kendala Sinkronisasi: ${err.message || 'Gagal tersambung ke Firebase Cloud.'}`);
    }
  }
}
window.paksaSinkronDriveManual = paksaSinkronDriveManual;

// 3. Sinkronkan Karya Siswa dari Cloud saat Siswa Login (Word Poster & Drive 7 Kebiasaan)
async function sinkronkanKaryaSiswaDariCloud(profile) {
  if (!isFirebaseConnected || !firebaseFirestoreInstance || !profile) return;

  const studentNis = profile.nis;
  const studentName = profile.nama;
  if (!studentNis && !studentName) return;

  try {
    // 3A. Tarik poster-poster Word dari Cloud
    let queryRef = firebaseFirestoreInstance.collection('karya_posters');
    if (studentNis) {
      queryRef = queryRef.where('studentNis', '==', studentNis);
    } else {
      queryRef = queryRef.where('studentName', '==', studentName);
    }

    const snapshot = await queryRef.get();
    if (!snapshot.empty) {
      const storageKey = getActiveStudentStorageKey('kreator_cilik_word_posters');
      let localList = [];
      try {
        localList = JSON.parse(localStorage.getItem(storageKey) || '[]');
      } catch (e) { localList = []; }

      let hasNewCloudItem = false;
      snapshot.forEach(doc => {
        const cloudItem = doc.data();
        const existIdx = localList.findIndex(p => p.id === cloudItem.id || (p.title && cloudItem.title && p.title.toLowerCase() === cloudItem.title.toLowerCase()));
        if (existIdx === -1) {
          localList.unshift(cloudItem);
          hasNewCloudItem = true;
        } else {
          // Perbarui image url jika versi cloud memiliki URL Storage yang valid
          if (cloudItem.image && !localList[existIdx].image) {
            localList[existIdx].image = cloudItem.image;
            hasNewCloudItem = true;
          }
        }
      });

      if (hasNewCloudItem) {
        localStorage.setItem(storageKey, JSON.stringify(localList));
        if (typeof renderGaleriPosterWord === 'function') {
          renderGaleriPosterWord();
        }
      }
    }

    // 3B. Tarik data Drive 7 Kebiasaan dari Cloud
    if (studentNis) {
      const driveDoc = await firebaseFirestoreInstance.collection('student_drives').doc(studentNis).get();
      if (driveDoc.exists) {
        const dData = driveDoc.data();
        if (dData && dData.driveData) {
          try {
            const parsed = JSON.parse(dData.driveData);
            const driveKey = getDriveStorageKey();
            localStorage.setItem(driveKey, JSON.stringify(parsed));
          } catch (e) {}
        }
      }
    }

    const nowStr = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' });
    localStorage.setItem(FIREBASE_LAST_SYNC_KEY, nowStr);
    perbaruiStatusFirebaseUI();
  } catch (err) {
    console.warn('Gagal sinkronkan karya siswa dari cloud:', err);
  }
}
window.sinkronkanKaryaSiswaDariCloud = sinkronkanKaryaSiswaDariCloud;

// 4. Unggah Semua Karya Lokal ke Cloud (Untuk Migrasi Komputer Guru / Siswa yang Sudah Ada)
async function unggahSemuaKaryaLokalKeCloud() {
  if (!isFirebaseConnected || !firebaseFirestoreInstance) {
    showToast('⚠️ Hubungkan ke Google Firebase terlebih dahulu sebelum melakukan sinkronisasi massal!', 'warning');
    return;
  }

  showToast('🔄 Mengunggah seluruh hasil karya poster & Drive siswa ke Server Cloud...', 'info');

  let uploadedCount = 0;
  try {
    // 1. Scan semua key localStorage yang terkait poster siswa
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key && key.includes('kreator_cilik_word_posters')) {
        try {
          const list = JSON.parse(localStorage.getItem(key) || '[]');
          if (Array.isArray(list)) {
            for (const p of list) {
              await unggahPosterKeCloud(p);
              uploadedCount++;
            }
          }
        } catch (e) {}
      }
    }

    // 2. Unggah Drive 7 Kebiasaan saat ini
    const driveCurrent = muatDrive7Kebiasaan();
    if (driveCurrent && Object.keys(driveCurrent).length > 0) {
      await unggahDriveKeCloud(driveCurrent);
    }

    try { playSound('fanfare'); } catch (e) {}
    showToast(`✅ Berhasil mengunggah ${uploadedCount} karya poster siswa ke Cloud Firebase! ☁️✨`, 'success');
  } catch (err) {
    console.error('Error sinkronisasi massal:', err);
    showToast('Terjadi kendala saat sinkronisasi massal: ' + err.message, 'error');
  }
}
window.unggahSemuaKaryaLokalKeCloud = unggahSemuaKaryaLokalKeCloud;

// Otomatis jalankan inisialisasi Firebase HANYA jika mode cloud disetujui (mencegah lag background network)
document.addEventListener('DOMContentLoaded', () => {
  setTimeout(() => {
    const isApproved = localStorage.getItem('educode_firebase_enabled_v1') === 'true';
    if (isApproved) {
      if (typeof loadFirebaseSDKs === 'function') {
        loadFirebaseSDKs().then(() => {
          initFirebaseClient();
        }).catch(() => {
          isFirebaseConnected = false;
          perbaruiStatusFirebaseUI();
        });
      } else {
        initFirebaseClient();
      }
    } else {
      isFirebaseConnected = false;
      perbaruiStatusFirebaseUI();
    }
  }, 500);
});







